window.EN_CONTENT={"source":"English for Palestine 6 (Pupil's Book 6A و 6B)","meta":{"source":{"6A":"https://elearn.azureedge.net/Books/c6/en6-p1.pdf","6B":"https://elearn.azureedge.net/Books/c6/en6-p2.pdf"},"notes":["Source: official Ministry of Education 'English for Palestine' NEW EDITION Pupil's Book 6A (Units 1-9) and 6B (Units 10-18), elearn.azureedge.net.","Units 5, 9, 14 and 18 are revision stories (4 pages each).","Period page refs are printed book page numbers (= PDF page numbers)."]},"units":[{"number":1,"semester":1,"title":"My summer holiday","page":4,"pages":[4,11],"revision":false,"vocabulary":[{"word":"accident","arabic":"حادث","example":"Then she had an accident.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"awful","arabic":"فظيع","example":"","source":"book contents / word box","example_note":""},{"word":"back","arabic":"عائد / رجع","example":"Amy and Ben came back to Palestine.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"bang","arabic":"يرتطم / يضرب","example":"She banged her head and arm.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"call","arabic":"يتصل / ينادي","example":"Amy's friend called a teacher and Amy went to the hospital.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"crash","arabic":"يصطدم بقوة","example":"","source":"book contents / word box","example_note":""},{"word":"fall","arabic":"يسقط","example":"My friend Ann heard me fall.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"miss","arabic":"يشتاق إلى","example":"Yes, I had a great time, but I missed you too!","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"stairs","arabic":"درج","example":"She fell down the stairs of the tree house and broke her arm.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"still","arabic":"ما زال","example":"Amy and Ben still had fun on their holiday.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"summer camp","arabic":"مخيم صيفي","example":"Did you have a nice time at summer camp?","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"tired","arabic":"متعب","example":"Amy was very tired.","source":"book contents / word box","example_note":"sentence from the unit text"}],"sentences":["Welcome back!","Oh dear!","Phew!","Thank goodness!"],"dialogues":[{"title":"Period 1 conversation","page":4,"source":"speech bubbles from Pupil's Book; speakers taken from the picture captions","lines":[{"speaker":"Rania","gender":"f","gender_verified":true,"text":"Welcome back, Amy! I missed you. Did you have a nice time at summer camp?"},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"Yes, I had a great time, but I missed you too!"},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"Oh dear! What happened to your arm?"},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"I fell down and broke it."},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"How awful!"},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"My friend Ann heard me fall. She called a teacher and I went to hospital."},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"Phew! Thank goodness!"},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"Did you still have a good time at summer camp?"},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"Oh yes, we had a great time. We played lots of sports and we went swimming every day! Look – my friends wrote their names."}]}],"texts":[{"title":"My summer holiday","page":4,"paragraphs":["Amy and Ben came back to Palestine. Rania and Amy were talking.","We played all day. Amy was very tired. Then she had an accident. She fell down the stairs of the tree house and broke her arm.","Amy climbed up the stairs of the tree house and fell back down and then crashed into the flowers. She banged her head and arm.","Amy told Rania about the accident. Amy's friend called a teacher and Amy went to the hospital.","Amy and Ben still had fun on their holiday. Amy's arm doesn't hurt anymore."]}],"grammar":[{"title":"الماضي البسيط (مراجعة)","explanation":"نستعمل الماضي البسيط لحدث انتهى في الماضي. الأفعال المنتظمة تأخذ ed مثل missed وcrashed، وبعضها شاذّ مثل fall → fell وbreak → broke. وفي السؤال والنفي نستعمل did مع الفعل في صيغته الأصلية.","examples":["Amy had an accident.","She fell down the stairs.","Did you have a nice time at summer camp?","Amy banged her head and arm."]},{"title":"علامات الترقيم: النقطة","explanation":"نبدأ الجملة بحرف كبير (capital letter) وننهيها بنقطة (full stop).","examples":["Last summer Amy broke her arm.","She fell down the stairs."]}],"grammar_en":["الماضي البسيط (مراجعة)","علامات الترقيم: النقطة"],"pronunciation":[],"functions":[],"writing":[],"task":"","seeds":[{"type":"gap_fill","prompt":"Then she had an _____.","answer":"accident"},{"type":"meaning_mcq","prompt":"accident","answer":"حادث","distractors":["مخيم صيفي","عائد / رجع","درج"]},{"type":"meaning_mcq","prompt":"awful","answer":"فظيع","distractors":["يصطدم بقوة","حادث","مخيم صيفي"]},{"type":"gap_fill","prompt":"Amy and Ben came _____ to Palestine.","answer":"back"},{"type":"meaning_mcq","prompt":"back","answer":"عائد / رجع","distractors":["يرتطم / يضرب","مخيم صيفي","درج"]},{"type":"meaning_mcq","prompt":"bang","answer":"يرتطم / يضرب","distractors":["يسقط","متعب","حادث"]},{"type":"meaning_mcq","prompt":"call","answer":"يتصل / ينادي","distractors":["يصطدم بقوة","درج","يرتطم / يضرب"]},{"type":"meaning_mcq","prompt":"crash","answer":"يصطدم بقوة","distractors":["يشتاق إلى","ما زال","مخيم صيفي"]},{"type":"gap_fill","prompt":"My friend Ann heard me _____.","answer":"fall"},{"type":"meaning_mcq","prompt":"fall","answer":"يسقط","distractors":["متعب","فظيع","يرتطم / يضرب"]},{"type":"meaning_mcq","prompt":"miss","answer":"يشتاق إلى","distractors":["مخيم صيفي","ما زال","يتصل / ينادي"]},{"type":"gap_fill","prompt":"She fell down the _____ of the tree house and broke her arm.","answer":"stairs"},{"type":"meaning_mcq","prompt":"stairs","answer":"درج","distractors":["متعب","مخيم صيفي","فظيع"]},{"type":"gap_fill","prompt":"Amy and Ben _____ had fun on their holiday.","answer":"still"},{"type":"meaning_mcq","prompt":"still","answer":"ما زال","distractors":["يسقط","يصطدم بقوة","فظيع"]},{"type":"gap_fill","prompt":"Did you have a nice time at _____?","answer":"summer camp"},{"type":"meaning_mcq","prompt":"summer camp","answer":"مخيم صيفي","distractors":["يصطدم بقوة","يسقط","يتصل / ينادي"]},{"type":"gap_fill","prompt":"Amy was very _____.","answer":"tired"},{"type":"meaning_mcq","prompt":"tired","answer":"متعب","distractors":["يشتاق إلى","فظيع","يرتطم / يضرب"]},{"type":"grammar_reorder","prompt":"an / Amy / accident / had","answer":"Amy had an accident."},{"type":"grammar_reorder","prompt":"down / the / She / stairs / fell","answer":"She fell down the stairs."},{"type":"grammar_reorder","prompt":"summer / her / broke / arm / Amy / Last","answer":"Last summer Amy broke her arm."},{"type":"grammar_reorder","prompt":"She / fell / stairs / the / down","answer":"She fell down the stairs."},{"type":"dialogue_order","lines":["Welcome back, Amy! I missed you. Did you have a nice time at summer camp?","Yes, I had a great time, but I missed you too!","Oh dear! What happened to your arm?","I fell down and broke it."]}],"verified":true,"notes":"Vocabulary from the book contents page; readings and speech bubbles verbatim from Period 1; Arabic meanings authored."},{"number":2,"semester":1,"title":"Good friends","page":12,"pages":[12,19],"revision":false,"vocabulary":[{"word":"anyone","arabic":"أيّ أحد","example":"I don't like arguing with anyone.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"argue","arabic":"يتجادل","example":"I don't like arguing with anyone.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"but","arabic":"لكن","example":"Rania needed her book but Fatima left it at home.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"cry","arabic":"يبكي","example":"I don't understand why you are crying.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"give back","arabic":"يُعيد","example":"I will give back your book.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"go away","arabic":"يذهب بعيدًا / ابتعد","example":"Bilal said to Ben 'Go away!","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"invite","arabic":"يدعو","example":"He invited Bilal to play.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"lend","arabic":"يُعير","example":"I lent Fatima my favourite book, but she left it at home.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"problem","arabic":"مشكلة","example":"She had a problem.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"quiz","arabic":"اختبار قصير / مسابقة","example":"Let's go home and do this quiz about friends!","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"share","arabic":"يشارك","example":"I like sharing my books with someone but I want them back.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"someone","arabic":"شخص ما","example":"I like sharing my books with someone but I want them back.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"understand","arabic":"يفهم","example":"I don't understand why you are crying.","source":"book contents / word box","example_note":"sentence from the unit text"}],"sentences":["What happened?","Go away!","I'm sorry."],"dialogues":[{"title":"Period 1 conversation","page":12,"source":"speech bubbles from Pupil's Book; speakers taken from the picture captions","lines":[{"speaker":"Amy","gender":"f","gender_verified":true,"text":"Rania, what happened? I don't understand why you are crying."},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"I have a problem. I lent Fatima my favourite book, but she left it at home. I need it."},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"I like sharing my books with someone but I want them back. I don't like arguing with anyone."},{"speaker":"Fatima","gender":"f","gender_verified":true,"text":"Sorry, Rania. I will give back your book."},{"speaker":"Ben","gender":"m","gender_verified":true,"text":"Why doesn't Bilal like playing with me?"},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Ben, don't be sad."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Hey Ben, let's ask Bilal."},{"speaker":"Ben","gender":"m","gender_verified":true,"text":"Come on Omar. Let's play basketball."},{"speaker":"Bilal","gender":"m","gender_verified":true,"text":"I'm sorry Ben."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Let's go home and do this quiz about friends!"}]}],"texts":[{"title":"Good friends","page":12,"paragraphs":["Rania was crying. She had a problem. Rania needed her book but Fatima left it at home.","Fatima gave back Rania's favourite book. Rania and Fatima were friends again.","Ben was very sad. Bilal said to Ben 'Go away! You're not my friend'. Omar said 'We can find someone nice to play with.'","Ben and Omar wanted to play basketball. Omar saw Bilal. He invited Bilal to play. Ben and Bilal were friends again."]}],"grammar":[{"title":"أداة الربط but","explanation":"نستعمل but لنربط فكرتين متعاكستين في جملة واحدة.","examples":["I lent Fatima my favourite book, but she left it at home.","I like sharing my books with someone but I want them back."]},{"title":"الحروف الكبيرة","explanation":"نكتب بحرف كبير أول الجملة وأسماء الأشخاص والأماكن والضمير I.","examples":["Rania and Fatima were friends again.","Omar saw Bilal."]}],"grammar_en":["أداة الربط but","الحروف الكبيرة"],"pronunciation":[],"functions":[],"writing":[],"task":"","seeds":[{"type":"gap_fill","prompt":"I don't like arguing with _____.","answer":"anyone"},{"type":"meaning_mcq","prompt":"anyone","answer":"أيّ أحد","distractors":["يفهم","يُعيد","يُعير"]},{"type":"meaning_mcq","prompt":"argue","answer":"يتجادل","distractors":["مشكلة","يُعيد","يبكي"]},{"type":"gap_fill","prompt":"Rania needed her book _____ Fatima left it at home.","answer":"but"},{"type":"meaning_mcq","prompt":"but","answer":"لكن","distractors":["يشارك","يُعيد","اختبار قصير / مسابقة"]},{"type":"meaning_mcq","prompt":"cry","answer":"يبكي","distractors":["أيّ أحد","يُعيد","لكن"]},{"type":"gap_fill","prompt":"I will _____ your book.","answer":"give back"},{"type":"meaning_mcq","prompt":"give back","answer":"يُعيد","distractors":["أيّ أحد","شخص ما","يدعو"]},{"type":"gap_fill","prompt":"Bilal said to Ben '_____!","answer":"Go away"},{"type":"meaning_mcq","prompt":"go away","answer":"يذهب بعيدًا / ابتعد","distractors":["اختبار قصير / مسابقة","شخص ما","يشارك"]},{"type":"meaning_mcq","prompt":"invite","answer":"يدعو","distractors":["يشارك","يُعيد","يذهب بعيدًا / ابتعد"]},{"type":"meaning_mcq","prompt":"lend","answer":"يُعير","distractors":["يدعو","اختبار قصير / مسابقة","يفهم"]},{"type":"gap_fill","prompt":"She had a _____.","answer":"problem"},{"type":"meaning_mcq","prompt":"problem","answer":"مشكلة","distractors":["يُعيد","لكن","يُعير"]},{"type":"gap_fill","prompt":"Let's go home and do this _____ about friends!","answer":"quiz"},{"type":"meaning_mcq","prompt":"quiz","answer":"اختبار قصير / مسابقة","distractors":["أيّ أحد","لكن","يدعو"]},{"type":"meaning_mcq","prompt":"share","answer":"يشارك","distractors":["اختبار قصير / مسابقة","يدعو","يتجادل"]},{"type":"gap_fill","prompt":"I like sharing my books with _____ but I want them back.","answer":"someone"},{"type":"meaning_mcq","prompt":"someone","answer":"شخص ما","distractors":["يُعير","يبكي","يتجادل"]},{"type":"gap_fill","prompt":"I don't _____ why you are crying.","answer":"understand"},{"type":"meaning_mcq","prompt":"understand","answer":"يفهم","distractors":["اختبار قصير / مسابقة","يشارك","يُعير"]},{"type":"grammar_reorder","prompt":"she / but / lent / left / at / my / Fatima / home / I / favourite / it / book,","answer":"I lent Fatima my favourite book, but she left it at home."},{"type":"grammar_reorder","prompt":"but / sharing / I / want / like / them / books / someone / back / my / with / I","answer":"I like sharing my books with someone but I want them back."},{"type":"grammar_reorder","prompt":"friends / Fatima / were / and / again / Rania","answer":"Rania and Fatima were friends again."},{"type":"grammar_reorder","prompt":"Bilal / saw / Omar","answer":"Omar saw Bilal."},{"type":"dialogue_order","lines":["Rania, what happened? I don't understand why you are crying.","I have a problem. I lent Fatima my favourite book, but she left it at home. I need it.","I like sharing my books with someone but I want them back. I don't like arguing with anyone.","Sorry, Rania. I will give back your book."]}],"verified":true,"notes":"Vocabulary from the book contents page; readings and speech bubbles verbatim from Period 1; Arabic meanings authored."},{"number":3,"semester":1,"title":"Summer adventures","page":20,"pages":[20,27],"revision":false,"vocabulary":[{"word":"thirteenth","arabic":"الثالث عشر","example":"","source":"book contents / word box","example_note":""},{"word":"fourteenth","arabic":"الرابع عشر","example":"","source":"book contents / word box","example_note":""},{"word":"fifteenth","arabic":"الخامس عشر","example":"","source":"book contents / word box","example_note":""},{"word":"sixteenth","arabic":"السادس عشر","example":"","source":"book contents / word box","example_note":""},{"word":"seventeenth","arabic":"السابع عشر","example":"","source":"book contents / word box","example_note":""},{"word":"eighteenth","arabic":"الثامن عشر","example":"","source":"book contents / word box","example_note":""},{"word":"nineteenth","arabic":"التاسع عشر","example":"","source":"book contents / word box","example_note":""},{"word":"twentieth","arabic":"العشرون","example":"","source":"book contents / word box","example_note":""},{"word":"twenty-first","arabic":"الحادي والعشرون","example":"","source":"book contents / word box","example_note":""},{"word":"thirtieth","arabic":"الثلاثون","example":"","source":"book contents / word box","example_note":""},{"word":"adventure","arabic":"مغامرة","example":"Amy had an adventure on the 13th of August in England.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"burst","arabic":"ينفجر","example":"Two of the car wheels burst!","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"chase","arabic":"يطارد","example":"A wolf was chasing the sheep when they ran away.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"turn over","arabic":"ينقلب","example":"We were going down the river when the boat turned over.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"when","arabic":"عندما","example":"A wolf was chasing the sheep when they ran away.","source":"book contents / word box","example_note":"sentence from the unit text"}],"sentences":["Ouch!","How wonderful!","Oh, it did!"],"dialogues":[{"title":"Period 1 conversation","page":20,"source":"speech bubbles from Pupil's Book; speakers taken from the picture captions","lines":[{"speaker":"Rania","gender":"f","gender_verified":true,"text":"You had some adventures last summer."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Two of the car wheels burst! The first on the day we were travelling to the farm and the second on the day we left the farm."},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"We were going down the river when the boat turned over. My shoes floated in the water!"},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"Oh Amy, what are you doing? Why are you in the river?"},{"speaker":"Ben","gender":"m","gender_verified":true,"text":"Ouch! That hurt!"},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Oh it did! I went to Jericho and won a bike race. I was looking at my parents and sister when I fell off my bike. Everyone laughed."},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"We stayed in a beautiful valley for three days on summer camp. We were hiking when we saw some baby birds trying to fly."},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"How wonderful! Well, we were riding horses in England when we lost our way. The clever horses took us back to the farm."}]}],"texts":[{"title":"Summer adventures","page":20,"paragraphs":["Omar's family stayed at their aunt's sheep farm from the 15th – 21st of July. A wolf was chasing the sheep when they ran away.","Amy had an adventure on the 13th of August in England. It was great fun.","Omar was telling Ben about his biking holiday on the 14th of August.","Rania's family went on holiday from the 15th to the 18th of August. Amy's family went horse riding on the 30th of August."]}],"grammar":[{"title":"الماضي المستمر مع when","explanation":"نستعمل الماضي المستمر (was / were + الفعل + ing) لحدث كان مستمرًّا في الماضي، ثم نذكر بعد when الحدث القصير الذي قطعه بالماضي البسيط.","examples":["A wolf was chasing the sheep when they ran away.","We were going down the river when the boat turned over.","We were hiking when we saw some baby birds trying to fly."]},{"title":"الأعداد الترتيبية والتواريخ","explanation":"نكتب التاريخ بالعدد الترتيبي: the 13th of August، ونقرؤه the thirteenth of August.","examples":["Amy had an adventure on the 13th of August.","Amy's family went horse riding on the 30th of August."]},{"title":"علامة الاستفهام","explanation":"ننهي السؤال بعلامة استفهام (question mark).","examples":["Why are you in the river?","What are you doing?"]}],"grammar_en":["الماضي المستمر مع when","الأعداد الترتيبية والتواريخ","علامة الاستفهام"],"pronunciation":[],"functions":[],"writing":[],"task":"","seeds":[{"type":"meaning_mcq","prompt":"thirteenth","answer":"الثالث عشر","distractors":["الحادي والعشرون","السادس عشر","يطارد"]},{"type":"meaning_mcq","prompt":"fourteenth","answer":"الرابع عشر","distractors":["العشرون","الحادي والعشرون","الثامن عشر"]},{"type":"meaning_mcq","prompt":"fifteenth","answer":"الخامس عشر","distractors":["ينفجر","ينقلب","الحادي والعشرون"]},{"type":"meaning_mcq","prompt":"sixteenth","answer":"السادس عشر","distractors":["التاسع عشر","عندما","ينفجر"]},{"type":"meaning_mcq","prompt":"seventeenth","answer":"السابع عشر","distractors":["الخامس عشر","مغامرة","العشرون"]},{"type":"meaning_mcq","prompt":"eighteenth","answer":"الثامن عشر","distractors":["يطارد","مغامرة","السابع عشر"]},{"type":"meaning_mcq","prompt":"nineteenth","answer":"التاسع عشر","distractors":["الثامن عشر","ينفجر","العشرون"]},{"type":"meaning_mcq","prompt":"twentieth","answer":"العشرون","distractors":["الحادي والعشرون","يطارد","الخامس عشر"]},{"type":"meaning_mcq","prompt":"twenty-first","answer":"الحادي والعشرون","distractors":["عندما","السابع عشر","الثلاثون"]},{"type":"meaning_mcq","prompt":"thirtieth","answer":"الثلاثون","distractors":["الثالث عشر","مغامرة","العشرون"]},{"type":"gap_fill","prompt":"Amy had an _____ on the 13th of August in England.","answer":"adventure"},{"type":"meaning_mcq","prompt":"adventure","answer":"مغامرة","distractors":["الثالث عشر","الخامس عشر","عندما"]},{"type":"gap_fill","prompt":"Two of the car wheels _____!","answer":"burst"},{"type":"meaning_mcq","prompt":"burst","answer":"ينفجر","distractors":["الثلاثون","ينقلب","عندما"]},{"type":"meaning_mcq","prompt":"chase","answer":"يطارد","distractors":["الرابع عشر","مغامرة","ينفجر"]},{"type":"meaning_mcq","prompt":"turn over","answer":"ينقلب","distractors":["الثامن عشر","عندما","العشرون"]},{"type":"gap_fill","prompt":"A wolf was chasing the sheep _____ they ran away.","answer":"when"},{"type":"meaning_mcq","prompt":"when","answer":"عندما","distractors":["ينقلب","الثلاثون","الثالث عشر"]},{"type":"grammar_reorder","prompt":"chasing / was / the / they / A / away / when / sheep / wolf / ran","answer":"A wolf was chasing the sheep when they ran away."},{"type":"grammar_reorder","prompt":"were / river / turned / going / boat / when / over / the / We / down / the","answer":"We were going down the river when the boat turned over."},{"type":"grammar_reorder","prompt":"had / Amy / the / adventure / 13th / of / an / on / August","answer":"Amy had an adventure on the 13th of August."},{"type":"grammar_reorder","prompt":"August / family / went / riding / on / 30th / horse / of / Amy's / the","answer":"Amy's family went horse riding on the 30th of August."},{"type":"grammar_reorder","prompt":"are / in / the / river / you / Why","answer":"Why are you in the river?"},{"type":"grammar_reorder","prompt":"doing / you / What / are","answer":"What are you doing?"},{"type":"dialogue_order","lines":["You had some adventures last summer.","Two of the car wheels burst! The first on the day we were travelling to the farm and the second on the day we left the farm.","We were going down the river when the boat turned over. My shoes floated in the water!","Oh Amy, what are you doing? Why are you in the river?"]}],"verified":true,"notes":"Vocabulary from the book contents page; readings and speech bubbles verbatim from Period 1; Arabic meanings authored."},{"number":4,"semester":1,"title":"Films I like","page":28,"pages":[28,35],"revision":false,"vocabulary":[{"word":"attack","arabic":"يهاجم","example":"While the young ox was eating, the tiger attacked it.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"diver","arabic":"غوّاص","example":"A dolphin rescued a diver when he got tired and stopped swimming.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"fight","arabic":"يتقاتل","example":"While big green fish were fighting, the small orange fish took their food.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"funny","arabic":"مضحك","example":"Amy told Rania about a funny cartoon.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"mouse","arabic":"فأر","example":"A dog was chasing a cat and a cat was chasing a mouse.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"noise","arabic":"ضجيج","example":"And then an angry man got up when he heard the noise and chased them all.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"other","arabic":"آخر","example":"The young ox was not near the other oxen.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"ox","arabic":"ثور","example":"The young ox was not near the other oxen.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"push","arabic":"يدفع","example":"The dolphin swam under the diver and pushed him to his boat.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"safe","arabic":"آمن","example":"The dolphin kept the diver safe.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"together","arabic":"معًا","example":"Oxen need to stay together then they are safe.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"while","arabic":"بينما","example":"While the young ox was eating, the tiger attacked it.","source":"book contents / word box","example_note":"sentence from the unit text"}],"sentences":["Poor ox!","How clever!"],"dialogues":[{"title":"Period 1 conversation","page":28,"source":"speech bubbles from Pupil's Book; speakers taken from the picture captions","lines":[{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Oxen need to stay together then they are safe."},{"speaker":"Ben","gender":"m","gender_verified":true,"text":"Oh no, poor ox!"},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"While the dog was chasing the cat, the mouse hid and watched it."},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"And then what happened?"},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"A cat crashed into a tree while it was chasing the mouse."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"I saw a great film. The dolphin swam under the diver and pushed him to his boat."},{"speaker":"Ben","gender":"m","gender_verified":true,"text":"What happened to the diver?"},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"He was fine! The dolphin rescued him!"},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"While big green fish were fighting, the small orange fish took their food."},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"How clever! While the small orange fish was eating the food, it hid under a green plant."}]}],"texts":[{"title":"Films I like","page":28,"paragraphs":["Omar's parents watched a film about tigers. The young ox was not near the other oxen. While the young ox was eating, the tiger attacked it.","Amy told Rania about a funny cartoon. A dog was chasing a cat and a cat was chasing a mouse. And then an angry man got up when he heard the noise and chased them all.","Omar told Ben about a rescue film. A dolphin rescued a diver when he got tired and stopped swimming. The dolphin kept the diver safe.","Amy's parents watched a film while she was doing her homework. They told her about the film."]}],"grammar":[{"title":"الماضي المستمر مع while","explanation":"نستعمل while مع الماضي المستمر لحدث طويل كان يجري، ويقع خلاله حدث آخر.","examples":["While the young ox was eating, the tiger attacked it.","Amy's parents watched a film while she was doing her homework.","A cat crashed into a tree while it was chasing the mouse."]},{"title":"الفاصلة","explanation":"نضع فاصلة (comma) بعد الجزء الذي يبدأ بـ while في أول الجملة، وبين الأشياء في القائمة.","examples":["While the dog was chasing the cat, the mouse hid and watched it."]}],"grammar_en":["الماضي المستمر مع while","الفاصلة"],"pronunciation":[],"functions":[],"writing":[],"task":"","seeds":[{"type":"meaning_mcq","prompt":"attack","answer":"يهاجم","distractors":["آخر","ضجيج","بينما"]},{"type":"gap_fill","prompt":"A dolphin rescued a _____ when he got tired and stopped swimming.","answer":"diver"},{"type":"meaning_mcq","prompt":"diver","answer":"غوّاص","distractors":["يهاجم","يتقاتل","آمن"]},{"type":"meaning_mcq","prompt":"fight","answer":"يتقاتل","distractors":["ضجيج","بينما","معًا"]},{"type":"gap_fill","prompt":"Amy told Rania about a _____ cartoon.","answer":"funny"},{"type":"meaning_mcq","prompt":"funny","answer":"مضحك","distractors":["يدفع","ثور","بينما"]},{"type":"gap_fill","prompt":"A dog was chasing a cat and a cat was chasing a _____.","answer":"mouse"},{"type":"meaning_mcq","prompt":"mouse","answer":"فأر","distractors":["آخر","يهاجم","غوّاص"]},{"type":"gap_fill","prompt":"And then an angry man got up when he heard the _____ and chased them all.","answer":"noise"},{"type":"meaning_mcq","prompt":"noise","answer":"ضجيج","distractors":["مضحك","معًا","بينما"]},{"type":"gap_fill","prompt":"The young ox was not near the _____ oxen.","answer":"other"},{"type":"meaning_mcq","prompt":"other","answer":"آخر","distractors":["آمن","يهاجم","يتقاتل"]},{"type":"gap_fill","prompt":"The young _____ was not near the other oxen.","answer":"ox"},{"type":"meaning_mcq","prompt":"ox","answer":"ثور","distractors":["ضجيج","بينما","يهاجم"]},{"type":"meaning_mcq","prompt":"push","answer":"يدفع","distractors":["يهاجم","مضحك","آخر"]},{"type":"gap_fill","prompt":"The dolphin kept the diver _____.","answer":"safe"},{"type":"meaning_mcq","prompt":"safe","answer":"آمن","distractors":["ضجيج","غوّاص","يتقاتل"]},{"type":"gap_fill","prompt":"Oxen need to stay _____ then they are safe.","answer":"together"},{"type":"meaning_mcq","prompt":"together","answer":"معًا","distractors":["بينما","غوّاص","آخر"]},{"type":"gap_fill","prompt":"_____ the young ox was eating, the tiger attacked it.","answer":"While"},{"type":"meaning_mcq","prompt":"while","answer":"بينما","distractors":["يدفع","يتقاتل","ثور"]},{"type":"grammar_reorder","prompt":"tiger / the / young / While / it / was / the / ox / eating, / attacked","answer":"While the young ox was eating, the tiger attacked it."},{"type":"grammar_reorder","prompt":"film / watched / doing / she / was / parents / while / homework / a / Amy's / her","answer":"Amy's parents watched a film while she was doing her homework."},{"type":"grammar_reorder","prompt":"was / mouse / hid / While / cat, / it / watched / dog / the / chasing / and / the / the","answer":"While the dog was chasing the cat, the mouse hid and watched it."},{"type":"dialogue_order","lines":["Oxen need to stay together then they are safe.","Oh no, poor ox!","While the dog was chasing the cat, the mouse hid and watched it.","And then what happened?"]}],"verified":true,"notes":"Vocabulary from the book contents page; readings and speech bubbles verbatim from Period 1; Arabic meanings authored."},{"number":5,"semester":1,"title":"The oxen and the lion","page":36,"pages":[36,39],"revision":true,"vocabulary":[{"word":"once upon a time","arabic":"كان يا ما كان","example":"Once upon a time, there were two oxen.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"strong","arabic":"قوي","example":"The lion wanted to eat the oxen but the two oxen together were very strong.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"stronger","arabic":"أقوى","example":"I'm stronger than the black ox.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"the strongest","arabic":"الأقوى","example":"I'm the strongest! Come and get me!","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"lion","arabic":"أسد","example":"One day they were eating when a lion saw them.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"hungry","arabic":"جائع","example":"","source":"book contents / word box","example_note":""},{"word":"idea","arabic":"فكرة","example":"The lion had an idea.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"quiet","arabic":"هادئ","example":"","source":"book contents / word box","example_note":""},{"word":"clever","arabic":"ذكي","example":"The lion was clever.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"tired","arabic":"متعب","example":"The oxen were getting tired when the lion attacked the brown ox.","source":"book contents / word box","example_note":"sentence from the unit text"}],"sentences":["Who do you think you are?","Come and get me!"],"dialogues":[{"title":"Period 1 conversation","page":36,"source":"speech bubbles from Pupil's Book; speakers taken from the picture captions","lines":[{"speaker":"Lion","gender":"m","gender_verified":true,"text":"They look good to eat!"},{"speaker":"Lion","gender":"m","gender_verified":true,"text":"Who is stronger?"},{"speaker":"Black ox","gender":"m","gender_verified":true,"text":"We are both strong."},{"speaker":"Brown ox","gender":"m","gender_verified":true,"text":"I'm stronger than the black ox. I always help him."},{"speaker":"Brown ox","gender":"m","gender_verified":true,"text":"You are not stronger than me! Who do you think you are?"},{"speaker":"Brown ox","gender":"m","gender_verified":true,"text":"I'm the strongest! Come and get me!"},{"speaker":"Lion","gender":"m","gender_verified":true,"text":"Oh good. They are fighting and both are getting tired!"}]}],"texts":[{"title":"The oxen and the lion","page":36,"paragraphs":["Once upon a time, there were two oxen. They were very good friends. They ate and played together. One day they were eating when a lion saw them. He was hungry. He wanted to eat them. The lion had an idea.","The lion spoke in a quiet voice to the black ox while the brown ox was eating. The lion wanted to eat the oxen but the two oxen together were very strong. He could not fight them together.","The lion spoke to the brown ox while the black ox was eating. The lion told the same story to the brown ox. The lion wanted the oxen to argue and fight.","The lion was clever. The lion watched the oxen while they were fighting. The oxen were getting tired when the lion attacked the brown ox. The lion ate the brown ox. The black ox had no friends. He was not strong. The lion attacked him while he was sleeping. The lion ate the black ox."]}],"grammar":[{"title":"مراجعة: الماضي المستمر مع when و while","explanation":"نراجع لغة الوحدات 1–4: حدث طويل في الماضي المستمر وحدث قصير في الماضي البسيط.","examples":["One day they were eating when a lion saw them.","The lion watched the oxen while they were fighting."]},{"title":"صيغة المقارنة والتفضيل","explanation":"نقارن بين اثنين بـ stronger than، ونفضّل واحدًا على الجميع بـ the strongest.","examples":["You are not stronger than me!","I'm the strongest!"]}],"grammar_en":["مراجعة: الماضي المستمر مع when و while","صيغة المقارنة والتفضيل"],"pronunciation":[],"functions":[],"writing":[],"task":"","seeds":[{"type":"gap_fill","prompt":"_____, there were two oxen.","answer":"Once upon a time"},{"type":"meaning_mcq","prompt":"once upon a time","answer":"كان يا ما كان","distractors":["أسد","فكرة","الأقوى"]},{"type":"gap_fill","prompt":"The lion wanted to eat the oxen but the two oxen together were very _____.","answer":"strong"},{"type":"meaning_mcq","prompt":"strong","answer":"قوي","distractors":["الأقوى","متعب","أقوى"]},{"type":"gap_fill","prompt":"I'm _____ than the black ox.","answer":"stronger"},{"type":"meaning_mcq","prompt":"stronger","answer":"أقوى","distractors":["الأقوى","هادئ","كان يا ما كان"]},{"type":"meaning_mcq","prompt":"the strongest","answer":"الأقوى","distractors":["كان يا ما كان","متعب","ذكي"]},{"type":"gap_fill","prompt":"One day they were eating when a _____ saw them.","answer":"lion"},{"type":"meaning_mcq","prompt":"lion","answer":"أسد","distractors":["ذكي","كان يا ما كان","متعب"]},{"type":"meaning_mcq","prompt":"hungry","answer":"جائع","distractors":["متعب","قوي","فكرة"]},{"type":"gap_fill","prompt":"The lion had an _____.","answer":"idea"},{"type":"meaning_mcq","prompt":"idea","answer":"فكرة","distractors":["جائع","كان يا ما كان","ذكي"]},{"type":"meaning_mcq","prompt":"quiet","answer":"هادئ","distractors":["متعب","الأقوى","فكرة"]},{"type":"gap_fill","prompt":"The lion was _____.","answer":"clever"},{"type":"meaning_mcq","prompt":"clever","answer":"ذكي","distractors":["فكرة","الأقوى","متعب"]},{"type":"gap_fill","prompt":"The oxen were getting _____ when the lion attacked the brown ox.","answer":"tired"},{"type":"meaning_mcq","prompt":"tired","answer":"متعب","distractors":["أسد","قوي","الأقوى"]},{"type":"grammar_reorder","prompt":"day / One / they / when / were / saw / eating / lion / a / them","answer":"One day they were eating when a lion saw them."},{"type":"grammar_reorder","prompt":"The / they / while / were / watched / oxen / lion / fighting / the","answer":"The lion watched the oxen while they were fighting."},{"type":"grammar_reorder","prompt":"me / than / are / stronger / You / not","answer":"You are not stronger than me!"},{"type":"grammar_reorder","prompt":"strongest / the / I'm","answer":"I'm the strongest!"},{"type":"dialogue_order","lines":["They look good to eat!","Who is stronger?","We are both strong.","I'm stronger than the black ox. I always help him."]}],"verified":false,"notes":"Revision unit; Vocabulary from the book contents page; readings and speech bubbles verbatim from Period 1; Arabic meanings authored."},{"number":6,"semester":1,"title":"Healthy food","page":40,"pages":[40,47],"revision":false,"vocabulary":[{"word":"advice","arabic":"نصيحة","example":"That is good advice.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"a little","arabic":"قليل","example":"The bottom of the pyramid shows foods you should always eat.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"because","arabic":"لأنّ","example":"Mum thinks Rania and Omar should eat lots of fruit and vegetables because they are healthy.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"bottom","arabic":"أسفل","example":"The bottom of the pyramid shows foods you should always eat.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"burger","arabic":"برغر","example":"We shouldn't buy fizzy drinks or burgers.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"fizzy drink","arabic":"مشروب غازي","example":"The children should not drink fizzy drinks because they are very sweet.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"fried","arabic":"مقلي","example":"You shouldn't eat lots of fried food.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"prefer","arabic":"يفضّل","example":"I prefer healthy food.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"pyramid","arabic":"هرم","example":"The top of the pyramid shows foods you should only eat sometimes.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"should","arabic":"ينبغي","example":"The top of the pyramid shows foods you should only eat sometimes.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"soup","arabic":"حساء","example":"Vegetable soup is good for you!","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"sweet","arabic":"حلو","example":"The children should not drink fizzy drinks because they are very sweet.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"top","arabic":"قمّة / أعلى","example":"The top of the pyramid shows foods you should only eat sometimes.","source":"book contents / word box","example_note":"sentence from the unit text"}],"sentences":["Let me think.","It's not healthy!"],"dialogues":[{"title":"Period 1 conversation","page":40,"source":"speech bubbles from Pupil's Book; speakers taken from the picture captions","lines":[{"speaker":"Mr Ali","gender":"m","gender_verified":true,"text":"Amy, we call this a food pyramid. It shows you the food you should eat."},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"Should I eat rice and meat?"},{"speaker":"Mr Ali","gender":"m","gender_verified":true,"text":"Yes, you should. Rice and meat are good for you because they make you strong."},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"Should I eat ice-cream?"},{"speaker":"Mr Ali","gender":"m","gender_verified":true,"text":"Yes, but only a little because it's very sweet. Vegetable soup is good for you!"},{"speaker":"Mr Ali","gender":"m","gender_verified":true,"text":"You shouldn't eat lots of fried food."},{"speaker":"Ben","gender":"m","gender_verified":true,"text":"Why shouldn't we eat lots of fried food?"},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Let me think, because fried food makes you fat. It's not healthy."},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"Let's go on a picnic! I prefer healthy food. We should take some bread, vegetables, fruit and a little meat."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"We should take lots of water to drink because it's good for us. We shouldn't buy fizzy drinks or burgers."}]}],"texts":[{"title":"Healthy food","page":40,"paragraphs":["The top of the pyramid shows foods you should only eat sometimes. The bottom of the pyramid shows foods you should always eat.","Mr Ali's class are talking about food. They can eat all the food but they should only eat a little of some foods. That is good advice.","Mum thinks Rania and Omar should eat lots of fruit and vegetables because they are healthy.","The children should not drink fizzy drinks because they are very sweet."]}],"grammar":[{"title":"النصيحة بـ should و shouldn't","explanation":"نستعمل should لنقدّم نصيحة، و shouldn't لننصح بعدم فعل شيء، ويأتي بعدهما الفعل في صيغته الأصلية.","examples":["You shouldn't eat lots of fried food.","We should take lots of water to drink.","Should I eat rice and meat?"]},{"title":"أداة الربط because","explanation":"نستعمل because لنذكر السبب.","examples":["Rice and meat are good for you because they make you strong.","The children should not drink fizzy drinks because they are very sweet."]}],"grammar_en":["النصيحة بـ should و shouldn't","أداة الربط because"],"pronunciation":[],"functions":[],"writing":[],"task":"","seeds":[{"type":"gap_fill","prompt":"That is good _____.","answer":"advice"},{"type":"meaning_mcq","prompt":"advice","answer":"نصيحة","distractors":["حساء","قمّة / أعلى","قليل"]},{"type":"meaning_mcq","prompt":"a little","answer":"قليل","distractors":["مقلي","قمّة / أعلى","لأنّ"]},{"type":"gap_fill","prompt":"Mum thinks Rania and Omar should eat lots of fruit and vegetables _____ they are healthy.","answer":"because"},{"type":"meaning_mcq","prompt":"because","answer":"لأنّ","distractors":["برغر","نصيحة","مقلي"]},{"type":"gap_fill","prompt":"The _____ of the pyramid shows foods you should always eat.","answer":"bottom"},{"type":"meaning_mcq","prompt":"bottom","answer":"أسفل","distractors":["قمّة / أعلى","مقلي","يفضّل"]},{"type":"meaning_mcq","prompt":"burger","answer":"برغر","distractors":["حلو","نصيحة","مقلي"]},{"type":"meaning_mcq","prompt":"fizzy drink","answer":"مشروب غازي","distractors":["لأنّ","نصيحة","حلو"]},{"type":"gap_fill","prompt":"You shouldn't eat lots of _____ food.","answer":"fried"},{"type":"meaning_mcq","prompt":"fried","answer":"مقلي","distractors":["مشروب غازي","قليل","هرم"]},{"type":"gap_fill","prompt":"I _____ healthy food.","answer":"prefer"},{"type":"meaning_mcq","prompt":"prefer","answer":"يفضّل","distractors":["نصيحة","هرم","برغر"]},{"type":"gap_fill","prompt":"The top of the _____ shows foods you should only eat sometimes.","answer":"pyramid"},{"type":"meaning_mcq","prompt":"pyramid","answer":"هرم","distractors":["قليل","حلو","حساء"]},{"type":"gap_fill","prompt":"The top of the pyramid shows foods you _____ only eat sometimes.","answer":"should"},{"type":"meaning_mcq","prompt":"should","answer":"ينبغي","distractors":["حساء","برغر","أسفل"]},{"type":"gap_fill","prompt":"Vegetable _____ is good for you!","answer":"soup"},{"type":"meaning_mcq","prompt":"soup","answer":"حساء","distractors":["لأنّ","قمّة / أعلى","مقلي"]},{"type":"gap_fill","prompt":"The children should not drink fizzy drinks because they are very _____.","answer":"sweet"},{"type":"meaning_mcq","prompt":"sweet","answer":"حلو","distractors":["هرم","لأنّ","أسفل"]},{"type":"gap_fill","prompt":"The _____ of the pyramid shows foods you should only eat sometimes.","answer":"top"},{"type":"meaning_mcq","prompt":"top","answer":"قمّة / أعلى","distractors":["حساء","مقلي","ينبغي"]},{"type":"grammar_reorder","prompt":"lots / of / fried / food / shouldn't / eat / You","answer":"You shouldn't eat lots of fried food."},{"type":"grammar_reorder","prompt":"of / We / should / lots / to / drink / take / water","answer":"We should take lots of water to drink."},{"type":"grammar_reorder","prompt":"they / meat / and / you / you / are / because / good / for / Rice / make / strong","answer":"Rice and meat are good for you because they make you strong."},{"type":"grammar_reorder","prompt":"because / The / fizzy / drinks / drink / should / children / they / sweet / not / are / very","answer":"The children should not drink fizzy drinks because they are very sweet."},{"type":"dialogue_order","lines":["Amy, we call this a food pyramid. It shows you the food you should eat.","Should I eat rice and meat?","Yes, you should. Rice and meat are good for you because they make you strong.","Should I eat ice-cream?"]}],"verified":true,"notes":"Vocabulary from the book contents page; readings and speech bubbles verbatim from Period 1; Arabic meanings authored."},{"number":7,"semester":1,"title":"The olive trees of Palestine","page":48,"pages":[48,55],"revision":false,"vocabulary":[{"word":"dish","arabic":"طبق","example":"We use olive oil in many dishes.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"harvest","arabic":"يحصد / يقطف المحصول","example":"Some olive trees are very old but you can harvest olives from them.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"hundred","arabic":"مئة","example":"","source":"book contents / word box","example_note":""},{"word":"love","arabic":"يحبّ","example":"I love your olives!","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"may","arabic":"يجوز / هل يمكنني","example":"May I try one?","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"million","arabic":"مليون","example":"There are millions of olive trees in Palestine.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"north","arabic":"الشمال","example":"Lots of them are in the north of Palestine.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"oil","arabic":"زيت","example":"In this place Omar's grandfather gets olive oil.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"soap","arabic":"صابون","example":"We use olive oil in some medicines and we make soap, too.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"thousand","arabic":"ألف","example":"","source":"book contents / word box","example_note":""},{"word":"useful","arabic":"مفيد","example":"Olives are very useful.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"wise","arabic":"حكيم","example":"He is wise because he knows that olives are very healthy.","source":"book contents / word box","example_note":"sentence from the unit text"}],"sentences":["Yes, of course.","Go ahead.","May I help you?","Yes, sure.","I'd love to help."],"dialogues":[{"title":"Period 1 conversation","page":48,"source":"speech bubbles from Pupil's Book; speakers taken from the picture captions","lines":[{"speaker":"Rania","gender":"f","gender_verified":true,"text":"Grandpa, how old are these trees?"},{"speaker":"Grandpa","gender":"m","gender_verified":true,"text":"Oh, let me think. My grandfather planted some of these trees, they are more than 150 years old."},{"speaker":"Grandma","gender":"f","gender_verified":true,"text":"Rania, there is olive oil in the fatoush. We use olive oil in many dishes."},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"I love your olives! May I try one? What do you do with them?"},{"speaker":"Grandma","gender":"f","gender_verified":true,"text":"Oh of course, go ahead. We eat them and we make olive oil! We use olive oil in some medicines and we make soap, too."},{"speaker":"Grandma","gender":"f","gender_verified":true,"text":"Would you like to help me make soap?"},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"Yes, I'd love to!"},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Grandfather, what's this place? What do you do here?"},{"speaker":"Grandpa","gender":"m","gender_verified":true,"text":"In this place we collect the olives after we harvest them. Then we press the olives and get olive oil."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"May I help you?"},{"speaker":"Grandpa","gender":"m","gender_verified":true,"text":"Yes, sure."},{"speaker":"Grandpa","gender":"m","gender_verified":true,"text":"Palestinians were growing olives here more than 5,000 years ago!"}]}],"texts":[{"title":"The olive trees of Palestine","page":48,"paragraphs":["Omar and Rania are visiting their grandfather's olive farm. Some olive trees are very old but you can harvest olives from them.","Rania and her grandmother are in the kitchen. They are talking about olives. Olives are very useful.","There are millions of olive trees in Palestine. Lots of them are in the north of Palestine.","Omar and his grandfather are in a big place. In this place Omar's grandfather gets olive oil. He is wise because he knows that olives are very healthy."]}],"grammar":[{"title":"الاستئذان بـ can و may","explanation":"نستعمل May I ...? أو Can I ...? لنطلب الإذن بأدب، ونجيب Yes, of course. أو Go ahead.","examples":["May I try one?","May I help you?","Can I help you?"]},{"title":"علامة التعجب","explanation":"نضع علامة التعجب (exclamation mark) بعد جملة فيها فرح أو دهشة.","examples":["I love your olives!","Yes, I'd love to!"]}],"grammar_en":["الاستئذان بـ can و may","علامة التعجب"],"pronunciation":[],"functions":[],"writing":[],"task":"","seeds":[{"type":"meaning_mcq","prompt":"dish","answer":"طبق","distractors":["يحصد / يقطف المحصول","مليون","يحبّ"]},{"type":"gap_fill","prompt":"Some olive trees are very old but you can _____ olives from them.","answer":"harvest"},{"type":"meaning_mcq","prompt":"harvest","answer":"يحصد / يقطف المحصول","distractors":["مئة","زيت","يجوز / هل يمكنني"]},{"type":"meaning_mcq","prompt":"hundred","answer":"مئة","distractors":["حكيم","يحصد / يقطف المحصول","يجوز / هل يمكنني"]},{"type":"gap_fill","prompt":"I _____ your olives!","answer":"love"},{"type":"meaning_mcq","prompt":"love","answer":"يحبّ","distractors":["زيت","حكيم","مئة"]},{"type":"gap_fill","prompt":"_____ I try one?","answer":"May"},{"type":"meaning_mcq","prompt":"may","answer":"يجوز / هل يمكنني","distractors":["مئة","ألف","طبق"]},{"type":"meaning_mcq","prompt":"million","answer":"مليون","distractors":["ألف","حكيم","صابون"]},{"type":"gap_fill","prompt":"Lots of them are in the _____ of Palestine.","answer":"north"},{"type":"meaning_mcq","prompt":"north","answer":"الشمال","distractors":["مليون","حكيم","زيت"]},{"type":"gap_fill","prompt":"In this place Omar's grandfather gets olive _____.","answer":"oil"},{"type":"meaning_mcq","prompt":"oil","answer":"زيت","distractors":["يجوز / هل يمكنني","يحصد / يقطف المحصول","حكيم"]},{"type":"gap_fill","prompt":"We use olive oil in some medicines and we make _____, too.","answer":"soap"},{"type":"meaning_mcq","prompt":"soap","answer":"صابون","distractors":["مئة","طبق","يحصد / يقطف المحصول"]},{"type":"meaning_mcq","prompt":"thousand","answer":"ألف","distractors":["مفيد","حكيم","مئة"]},{"type":"gap_fill","prompt":"Olives are very _____.","answer":"useful"},{"type":"meaning_mcq","prompt":"useful","answer":"مفيد","distractors":["صابون","حكيم","يحصد / يقطف المحصول"]},{"type":"gap_fill","prompt":"He is _____ because he knows that olives are very healthy.","answer":"wise"},{"type":"meaning_mcq","prompt":"wise","answer":"حكيم","distractors":["يحصد / يقطف المحصول","مفيد","ألف"]},{"type":"grammar_reorder","prompt":"I / one / try / May","answer":"May I try one?"},{"type":"grammar_reorder","prompt":"I / May / help / you","answer":"May I help you?"},{"type":"grammar_reorder","prompt":"love / olives / your / I","answer":"I love your olives!"},{"type":"grammar_reorder","prompt":"I'd / to / Yes, / love","answer":"Yes, I'd love to!"},{"type":"dialogue_order","lines":["Grandpa, how old are these trees?","Oh, let me think. My grandfather planted some of these trees, they are more than 150 years old.","Rania, there is olive oil in the fatoush. We use olive oil in many dishes.","I love your olives! May I try one? What do you do with them?"]}],"verified":true,"notes":"Vocabulary from the book contents page; readings and speech bubbles verbatim from Period 1; Arabic meanings authored."},{"number":8,"semester":1,"title":"Signs around us","page":56,"pages":[56,63],"revision":false,"vocabulary":[{"word":"boil","arabic":"يغلي","example":"You boil the potatoes and add in some onions and garlic.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"careful","arabic":"حذر","example":"You must be careful, it gets very hot.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"fire","arabic":"نار","example":"These signs say you must not walk on the grass and you must not make fires.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"garlic","arabic":"ثوم","example":"You boil the potatoes and add in some onions and garlic.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"grass","arabic":"عشب","example":"These signs say you must not walk on the grass and you must not make fires.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"hungry","arabic":"جائع","example":"","source":"book contents / word box","example_note":""},{"word":"must","arabic":"يجب","example":"These signs say you must not walk on the grass and you must not make fires.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"pepper","arabic":"فلفل","example":"You mustn't add lots of salt and pepper.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"ready","arabic":"جاهز","example":"They are getting the picnic ready.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"salt","arabic":"ملح","example":"You mustn't add lots of salt and pepper.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"sign","arabic":"لافتة / إشارة","example":"These signs say you must not walk on the grass and you must not make fires.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"smell","arabic":"يشمّ / رائحته","example":"Mmmm, this smells good.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"stone","arabic":"حجر","example":"Rania, stop playing with stones.","source":"book contents / word box","example_note":"sentence from the unit text"}],"sentences":["Could I help, please?","Don't walk there.","Sorry!"],"dialogues":[{"title":"Period 1 conversation","page":56,"source":"speech bubbles from Pupil's Book; speakers taken from the picture captions","lines":[{"speaker":"Ben","gender":"m","gender_verified":true,"text":"Could I help, please?"},{"speaker":"Mum","gender":"f","gender_verified":true,"text":"Yes of course. Ben, be careful! You mustn't add lots of salt and pepper. It's not healthy!"},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Ben, don't walk there!"},{"speaker":"Ben","gender":"m","gender_verified":true,"text":"Oops, sorry! And look at that sign. I think it says you mustn't make a fire here."},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"Rania, that sign says you mustn't pick the flowers."},{"speaker":"Mum","gender":"f","gender_verified":true,"text":"Rania, stop playing with stones. You must wash your hands."},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"OK, mum. Hey Amy, that sign says you mustn't ride your bike there."},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"Sorry, mum!"},{"speaker":"Mother","gender":"f","gender_verified":true,"text":"Mmmm, this smells good. I'm hungry. How do you make it?"},{"speaker":"Mum","gender":"f","gender_verified":true,"text":"You boil the potatoes and add in some onions and garlic."},{"speaker":"Mother","gender":"f","gender_verified":true,"text":"It's easy! You fry the chicken in a little olive oil. You must be careful, it gets very hot."}]}],"texts":[{"title":"Signs around us","page":56,"paragraphs":["Ben's mum is making a potato dish for the picnic. Ben is helping his mum in the kitchen.","Ben and Omar are at the park. These signs say you must not walk on the grass and you must not make fires.","Rania, Amy and their mums are in the park. They are getting the picnic ready.","The mothers are talking about the things they should do to make nice picnic food."]}],"grammar":[{"title":"الإلزام والمنع بـ must و mustn't","explanation":"نستعمل must لما يجب فعله، و mustn't (must not) لما يُمنع فعله، ويأتي بعدهما الفعل في صيغته الأصلية.","examples":["You must wash your hands.","You mustn't make a fire here.","You must not walk on the grass."]},{"title":"الفاصلة العليا (apostrophe)","explanation":"نستعمل الفاصلة العليا في الاختصار مثل mustn't و don't، وفي الملكية مثل Ben's mum.","examples":["Ben's mum is making a potato dish.","You mustn't pick the flowers."]}],"grammar_en":["الإلزام والمنع بـ must و mustn't","الفاصلة العليا (apostrophe)"],"pronunciation":[],"functions":[],"writing":[],"task":"","seeds":[{"type":"gap_fill","prompt":"You _____ the potatoes and add in some onions and garlic.","answer":"boil"},{"type":"meaning_mcq","prompt":"boil","answer":"يغلي","distractors":["حجر","ثوم","يجب"]},{"type":"gap_fill","prompt":"You must be _____, it gets very hot.","answer":"careful"},{"type":"meaning_mcq","prompt":"careful","answer":"حذر","distractors":["يشمّ / رائحته","جائع","نار"]},{"type":"meaning_mcq","prompt":"fire","answer":"نار","distractors":["جائع","يغلي","يشمّ / رائحته"]},{"type":"gap_fill","prompt":"You boil the potatoes and add in some onions and _____.","answer":"garlic"},{"type":"meaning_mcq","prompt":"garlic","answer":"ثوم","distractors":["يشمّ / رائحته","يغلي","جاهز"]},{"type":"gap_fill","prompt":"These signs say you must not walk on the _____ and you must not make fires.","answer":"grass"},{"type":"meaning_mcq","prompt":"grass","answer":"عشب","distractors":["يشمّ / رائحته","جاهز","يجب"]},{"type":"meaning_mcq","prompt":"hungry","answer":"جائع","distractors":["يغلي","حجر","عشب"]},{"type":"gap_fill","prompt":"These signs say you _____ not walk on the grass and you must not make fires.","answer":"must"},{"type":"meaning_mcq","prompt":"must","answer":"يجب","distractors":["حجر","حذر","فلفل"]},{"type":"gap_fill","prompt":"You mustn't add lots of salt and _____.","answer":"pepper"},{"type":"meaning_mcq","prompt":"pepper","answer":"فلفل","distractors":["لافتة / إشارة","جائع","حذر"]},{"type":"gap_fill","prompt":"They are getting the picnic _____.","answer":"ready"},{"type":"meaning_mcq","prompt":"ready","answer":"جاهز","distractors":["حجر","جائع","نار"]},{"type":"gap_fill","prompt":"You mustn't add lots of _____ and pepper.","answer":"salt"},{"type":"meaning_mcq","prompt":"salt","answer":"ملح","distractors":["نار","جائع","فلفل"]},{"type":"meaning_mcq","prompt":"sign","answer":"لافتة / إشارة","distractors":["حجر","يجب","يغلي"]},{"type":"meaning_mcq","prompt":"smell","answer":"يشمّ / رائحته","distractors":["جاهز","نار","حذر"]},{"type":"meaning_mcq","prompt":"stone","answer":"حجر","distractors":["فلفل","جائع","يغلي"]},{"type":"grammar_reorder","prompt":"must / your / hands / You / wash","answer":"You must wash your hands."},{"type":"grammar_reorder","prompt":"You / a / mustn't / make / here / fire","answer":"You mustn't make a fire here."},{"type":"grammar_reorder","prompt":"is / dish / a / potato / mum / making / Ben's","answer":"Ben's mum is making a potato dish."},{"type":"grammar_reorder","prompt":"flowers / You / pick / the / mustn't","answer":"You mustn't pick the flowers."},{"type":"dialogue_order","lines":["Could I help, please?","Yes of course. Ben, be careful! You mustn't add lots of salt and pepper. It's not healthy!","Ben, don't walk there!","Oops, sorry! And look at that sign. I think it says you mustn't make a fire here."]}],"verified":true,"notes":"Vocabulary from the book contents page; readings and speech bubbles verbatim from Period 1; Arabic meanings authored."},{"number":9,"semester":1,"title":"Stone soup","page":64,"pages":[64,67],"revision":true,"vocabulary":[{"word":"wise","arabic":"حكيم","example":"Once upon a time a wise grandfather arrived in a small town.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"town","arabic":"بلدة","example":"Once upon a time a wise grandfather arrived in a small town.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"soup","arabic":"حساء","example":"Mmmm, I know, I will make some soup.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"stone","arabic":"حجر","example":"The wise grandfather took a big white stone out of his bag.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"boil","arabic":"يغلي","example":"He put the water on the fire to boil.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"onions","arabic":"بصل","example":"Mmm, stone soup is good with some onions.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"garlic","arabic":"ثوم","example":"I have some garlic, too.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"carrots","arabic":"جزر","example":"It will be better with some carrots and potatoes.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"potatoes","arabic":"بطاطا","example":"It will be better with some carrots and potatoes.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"together","arabic":"معًا","example":"You must work together.","source":"book contents / word box","example_note":"sentence from the unit text"}],"sentences":["Be careful!","May I help you?"],"dialogues":[{"title":"Period 1 conversation","page":64,"source":"speech bubbles from Pupil's Book; speakers taken from the picture captions","lines":[{"speaker":"Grandfather","gender":"m","gender_verified":true,"text":"I'm tired and hungry. Could I have some food, please?"},{"speaker":"Woman","gender":"f","gender_verified":true,"text":"We're sorry, it's very dry here. No plants will grow. We have no food."},{"speaker":"Grandfather","gender":"m","gender_verified":true,"text":"Mmmm, I know, I will make some soup. Could I have some water please? I will make you some soup."},{"speaker":"Woman","gender":"f","gender_verified":true,"text":"Be careful! You mustn't get near the fire!"},{"speaker":"Grandfather","gender":"m","gender_verified":true,"text":"Mmm, stone soup is good with some onions."},{"speaker":"Man","gender":"m","gender_verified":true,"text":"Oh, I have some onions. I think you should have them. Good soup must have onions!"},{"speaker":"Girl","gender":"f","gender_verified":true,"text":"I have some tomatoes."},{"speaker":"Woman","gender":"f","gender_verified":true,"text":"May I help you? I have some garlic, too."},{"speaker":"Grandfather","gender":"m","gender_verified":true,"text":"This soup looks good now. It will be better with some carrots and potatoes. We mustn't put in lots of salt and pepper."},{"speaker":"Man","gender":"m","gender_verified":true,"text":"I think you should have this chicken."},{"speaker":"Woman","gender":"f","gender_verified":true,"text":"We love your soup! You are a wise grandfather!"},{"speaker":"Grandfather","gender":"m","gender_verified":true,"text":"It's YOUR soup because you all helped me. You must work together. Goodbye!"}]}],"texts":[{"title":"Stone soup","page":64,"paragraphs":["Once upon a time a wise grandfather arrived in a small town.","The wise grandfather thought and thought.","The wise grandfather took a big white stone out of his bag. He washed it and put it into the water. He put the water on the fire to boil.","The wise grandfather looked at the boiling water.","People went home and gave him all the things the wise grandfather wanted.","When everyone finished, the wise grandfather took the stone out of the soup, washed it and put it back in his bag. Then he went away."]}],"grammar":[{"title":"مراجعة: should و must و may","explanation":"نراجع لغة الوحدات 6–8: النصيحة بـ should، والإلزام بـ must، والاستئذان بـ May I.","examples":["I think you should have them.","You must work together.","May I help you?"]}],"grammar_en":["مراجعة: should و must و may"],"pronunciation":[],"functions":[],"writing":[],"task":"","seeds":[{"type":"gap_fill","prompt":"Once upon a time a _____ grandfather arrived in a small town.","answer":"wise"},{"type":"meaning_mcq","prompt":"wise","answer":"حكيم","distractors":["معًا","بطاطا","بصل"]},{"type":"gap_fill","prompt":"Once upon a time a wise grandfather arrived in a small _____.","answer":"town"},{"type":"meaning_mcq","prompt":"town","answer":"بلدة","distractors":["معًا","بصل","حساء"]},{"type":"gap_fill","prompt":"Mmmm, I know, I will make some _____.","answer":"soup"},{"type":"meaning_mcq","prompt":"soup","answer":"حساء","distractors":["حكيم","ثوم","معًا"]},{"type":"gap_fill","prompt":"The wise grandfather took a big white _____ out of his bag.","answer":"stone"},{"type":"meaning_mcq","prompt":"stone","answer":"حجر","distractors":["يغلي","بصل","بلدة"]},{"type":"gap_fill","prompt":"He put the water on the fire to _____.","answer":"boil"},{"type":"meaning_mcq","prompt":"boil","answer":"يغلي","distractors":["حساء","بصل","حكيم"]},{"type":"gap_fill","prompt":"Mmm, stone soup is good with some _____.","answer":"onions"},{"type":"meaning_mcq","prompt":"onions","answer":"بصل","distractors":["يغلي","معًا","ثوم"]},{"type":"gap_fill","prompt":"I have some _____, too.","answer":"garlic"},{"type":"meaning_mcq","prompt":"garlic","answer":"ثوم","distractors":["بصل","حجر","معًا"]},{"type":"gap_fill","prompt":"It will be better with some _____ and potatoes.","answer":"carrots"},{"type":"meaning_mcq","prompt":"carrots","answer":"جزر","distractors":["حساء","حكيم","بطاطا"]},{"type":"gap_fill","prompt":"It will be better with some carrots and _____.","answer":"potatoes"},{"type":"meaning_mcq","prompt":"potatoes","answer":"بطاطا","distractors":["بصل","حساء","جزر"]},{"type":"gap_fill","prompt":"You must work _____.","answer":"together"},{"type":"meaning_mcq","prompt":"together","answer":"معًا","distractors":["حساء","جزر","بصل"]},{"type":"grammar_reorder","prompt":"think / should / have / you / them / I","answer":"I think you should have them."},{"type":"grammar_reorder","prompt":"You / must / together / work","answer":"You must work together."},{"type":"dialogue_order","lines":["I'm tired and hungry. Could I have some food, please?","We're sorry, it's very dry here. No plants will grow. We have no food.","Mmmm, I know, I will make some soup. Could I have some water please? I will make you some soup.","Be careful! You mustn't get near the fire!"]}],"verified":false,"notes":"Revision unit; Vocabulary from the book contents page; readings and speech bubbles verbatim from Period 1; Arabic meanings authored."},{"number":10,"semester":2,"title":"A visit to the Dead Sea","page":4,"pages":[4,11],"revision":false,"vocabulary":[{"word":"anywhere","arabic":"أيّ مكان","example":"Have you ever been anywhere below sea level?","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"below sea level","arabic":"تحت مستوى سطح البحر","example":"It is 400 metres below sea level.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"desert","arabic":"صحراء","example":"There are many desert animals near the Dead Sea.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"ever","arabic":"من قبل / في أيّ وقت","example":"Have you ever been to the Dead Sea?","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"gazelle","arabic":"غزال","example":"I've seen a jerboa and a gazelle.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"jerboa","arabic":"جربوع","example":"I've seen a jerboa and a gazelle.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"man","arabic":"رجل","example":"The man in the picture is floating and reading a newspaper!","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"mud","arabic":"طين","example":"Amy and Rania are looking at photos of people with black mud on their bodies.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"oasis","arabic":"واحة","example":"Palm trees grow in an oasis because water comes from a spring.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"palm tree","arabic":"نخلة","example":"Palm trees grow in an oasis because water comes from a spring.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"rock","arabic":"صخرة","example":"","source":"book contents / word box","example_note":""},{"word":"salty","arabic":"مالح","example":"The water is very salty.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"skin","arabic":"جلد / بشرة","example":"The mud is a medicine for your skin.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"spring","arabic":"نبع","example":"Palm trees grow in an oasis because water comes from a spring.","source":"book contents / word box","example_note":"sentence from the unit text"}],"sentences":["Really?","Yuck!"],"dialogues":[{"title":"Period 1 conversation","page":4,"source":"speech bubbles from Pupil's Book; speakers taken from the picture captions","lines":[{"speaker":"Amy","gender":"f","gender_verified":true,"text":"Have you ever been to the Dead Sea?"},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"Yes, we went there two years ago."},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"Do you know that the Dead Sea is very salty? There are no fish or plants in this sea!"},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"Really?"},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"Have you ever floated in the sea?"},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"No, I haven't."},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"Have you ever put Dead Sea mud on your body?"},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"No, I haven't! Why would I do that?"},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"Ahhh, because it's a medicine and makes your skin feel great!"},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"Yuck!"},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"The Dead Sea is below sea level. Have you ever been anywhere below sea level?"},{"speaker":"Ben","gender":"m","gender_verified":true,"text":"No, I haven't."},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"Have you ever seen a desert animal?"},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Yes, I have. I've seen a jerboa and a gazelle."}]}],"texts":[{"title":"A visit to the Dead Sea","page":4,"paragraphs":["Amy and Rania are looking at the internet. They have found the Dead Sea. Rania visited the Dead Sea two years ago. The man in the picture is floating and reading a newspaper!","Amy, Rania and Ben are looking at pictures of the Dead Sea. The water is very salty. Palm trees grow in an oasis because water comes from a spring.","Amy and Rania are looking at photos of people with black mud on their bodies. The mud is a medicine for your skin.","Rania, Omar, Ben and Amy are talking about the Dead Sea. It is 400 metres below sea level. There are many desert animals near the Dead Sea."]}],"grammar":[{"title":"المضارع التام مع ever","explanation":"نسأل عن التجارب بـ Have you ever + التصريف الثالث للفعل؟ ونجيب Yes, I have. أو No, I haven't.","examples":["Have you ever been to the Dead Sea?","Have you ever floated in the sea?","I've seen a jerboa and a gazelle."]},{"title":"مراجعة الماضي البسيط","explanation":"نستعمل الماضي البسيط مع زمن محدّد مثل two years ago.","examples":["Rania visited the Dead Sea two years ago.","Yes, we went there two years ago."]}],"grammar_en":["المضارع التام مع ever","مراجعة الماضي البسيط"],"pronunciation":[],"functions":[],"writing":[],"task":"","seeds":[{"type":"gap_fill","prompt":"Have you ever been _____ below sea level?","answer":"anywhere"},{"type":"meaning_mcq","prompt":"anywhere","answer":"أيّ مكان","distractors":["صخرة","واحة","جربوع"]},{"type":"gap_fill","prompt":"It is 400 metres _____.","answer":"below sea level"},{"type":"meaning_mcq","prompt":"below sea level","answer":"تحت مستوى سطح البحر","distractors":["غزال","مالح","أيّ مكان"]},{"type":"gap_fill","prompt":"There are many _____ animals near the Dead Sea.","answer":"desert"},{"type":"meaning_mcq","prompt":"desert","answer":"صحراء","distractors":["واحة","مالح","جلد / بشرة"]},{"type":"gap_fill","prompt":"Have you _____ been to the Dead Sea?","answer":"ever"},{"type":"meaning_mcq","prompt":"ever","answer":"من قبل / في أيّ وقت","distractors":["نخلة","نبع","جربوع"]},{"type":"gap_fill","prompt":"I've seen a jerboa and a _____.","answer":"gazelle"},{"type":"meaning_mcq","prompt":"gazelle","answer":"غزال","distractors":["نخلة","جربوع","مالح"]},{"type":"gap_fill","prompt":"I've seen a _____ and a gazelle.","answer":"jerboa"},{"type":"meaning_mcq","prompt":"jerboa","answer":"جربوع","distractors":["رجل","غزال","طين"]},{"type":"gap_fill","prompt":"The _____ in the picture is floating and reading a newspaper!","answer":"man"},{"type":"meaning_mcq","prompt":"man","answer":"رجل","distractors":["جلد / بشرة","جربوع","تحت مستوى سطح البحر"]},{"type":"gap_fill","prompt":"Amy and Rania are looking at photos of people with black _____ on their bodies.","answer":"mud"},{"type":"meaning_mcq","prompt":"mud","answer":"طين","distractors":["نبع","نخلة","رجل"]},{"type":"gap_fill","prompt":"Palm trees grow in an _____ because water comes from a spring.","answer":"oasis"},{"type":"meaning_mcq","prompt":"oasis","answer":"واحة","distractors":["مالح","صحراء","غزال"]},{"type":"meaning_mcq","prompt":"palm tree","answer":"نخلة","distractors":["أيّ مكان","مالح","واحة"]},{"type":"meaning_mcq","prompt":"rock","answer":"صخرة","distractors":["جربوع","مالح","واحة"]},{"type":"gap_fill","prompt":"The water is very _____.","answer":"salty"},{"type":"meaning_mcq","prompt":"salty","answer":"مالح","distractors":["أيّ مكان","تحت مستوى سطح البحر","صخرة"]},{"type":"gap_fill","prompt":"The mud is a medicine for your _____.","answer":"skin"},{"type":"meaning_mcq","prompt":"skin","answer":"جلد / بشرة","distractors":["تحت مستوى سطح البحر","أيّ مكان","طين"]},{"type":"gap_fill","prompt":"Palm trees grow in an oasis because water comes from a _____.","answer":"spring"},{"type":"meaning_mcq","prompt":"spring","answer":"نبع","distractors":["رجل","واحة","تحت مستوى سطح البحر"]},{"type":"grammar_reorder","prompt":"ever / the / Sea / Dead / Have / been / you / to","answer":"Have you ever been to the Dead Sea?"},{"type":"grammar_reorder","prompt":"ever / floated / the / Have / sea / in / you","answer":"Have you ever floated in the sea?"},{"type":"grammar_reorder","prompt":"ago / Dead / two / the / Sea / Rania / years / visited","answer":"Rania visited the Dead Sea two years ago."},{"type":"grammar_reorder","prompt":"ago / two / years / there / Yes, / went / we","answer":"Yes, we went there two years ago."},{"type":"dialogue_order","lines":["Have you ever been to the Dead Sea?","Yes, we went there two years ago.","Do you know that the Dead Sea is very salty? There are no fish or plants in this sea!","Really?"]}],"verified":true,"notes":"Vocabulary from the book contents page; readings and speech bubbles verbatim from Period 1; Arabic meanings authored."},{"number":11,"semester":2,"title":"Exciting things to do","page":12,"pages":[12,19],"revision":false,"vocabulary":[{"word":"bat","arabic":"خفّاش","example":"I've seen bats flying out of a cave at night.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"cave","arabic":"كهف","example":"I've seen bats flying out of a cave at night.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"coral","arabic":"مرجان","example":"But I've swum under the water and I've seen coral!","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"flippers","arabic":"زعانف السباحة","example":"Have you ever used goggles and flippers?","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"goggles","arabic":"نظارة سباحة","example":"Have you ever used goggles and flippers?","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"hedgehog","arabic":"قنفذ","example":"I saw wild cats and a hedgehog while camping.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"never","arabic":"أبدًا / لم ... قطّ","example":"No, I've never used goggles and flippers.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"sail","arabic":"يبحر","example":"Have you ever sailed in a boat?","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"star","arabic":"نجمة","example":"Have you ever slept under the stars?","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"sunrise","arabic":"شروق الشمس","example":"Have you ever got up at sunrise?","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"sunset","arabic":"غروب الشمس","example":"","source":"book contents / word box","example_note":""},{"word":"wild cat","arabic":"قطّ بري","example":"I saw wild cats and a hedgehog while camping.","source":"book contents / word box","example_note":"sentence from the unit text"}],"sentences":["Yes, of course!"],"dialogues":[{"title":"Period 1 conversation","page":12,"source":"speech bubbles from Pupil's Book; speakers taken from the picture captions","lines":[{"speaker":"Ben","gender":"m","gender_verified":true,"text":"Have you ever sailed in a boat?"},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Yes, I have. I sailed in a boat at summer camp last year."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Have you ever used goggles and flippers?"},{"speaker":"Ben","gender":"m","gender_verified":true,"text":"No, I've never used goggles and flippers. But I've swum under the water and I've seen coral!"},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"Have you ever ridden a camel?"},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"Yes, of course! In Jericho. I love riding camels."},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"Have you ever ridden a horse?"},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"Yes! I love horse riding. It's great fun!"},{"speaker":"Mr Ali","gender":"m","gender_verified":true,"text":"Has anyone seen desert animals?"},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Yes, I have. I saw wild cats and a hedgehog while camping."},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"I've seen bats flying out of a cave at night."},{"speaker":"Omar's dad","gender":"m","gender_verified":true,"text":"Have you ever camped?"},{"speaker":"Ben's dad","gender":"m","gender_verified":true,"text":"Yes, of course, when I was young! We camped at the Dead Sea. Have you ever slept under the stars?"},{"speaker":"Omar's dad","gender":"m","gender_verified":true,"text":"Yes! Have you ever got up at sunrise?"},{"speaker":"Ben's dad","gender":"m","gender_verified":true,"text":"Yes I have. At the Dead Sea, it's cool at sunrise."}]}],"texts":[{"title":"Exciting things to do","page":12,"paragraphs":["Omar and Ben are talking about things they have done.","Rania and Amy are talking about things they have done.","Mr Ali is talking to his class about desert animals in Palestine.","Omar and Ben's dads are talking about what they did when they were young."]}],"grammar":[{"title":"المضارع التام مع never","explanation":"نستعمل never مع المضارع التام لنقول إننا لم نفعل الشيء في حياتنا قطّ: I've never + التصريف الثالث.","examples":["I've never used goggles and flippers.","I've swum under the water and I've seen coral!","Have you ever ridden a camel?"]}],"grammar_en":["المضارع التام مع never"],"pronunciation":[],"functions":[],"writing":[],"task":"","seeds":[{"type":"meaning_mcq","prompt":"bat","answer":"خفّاش","distractors":["قطّ بري","كهف","مرجان"]},{"type":"gap_fill","prompt":"I've seen bats flying out of a _____ at night.","answer":"cave"},{"type":"meaning_mcq","prompt":"cave","answer":"كهف","distractors":["قنفذ","زعانف السباحة","شروق الشمس"]},{"type":"gap_fill","prompt":"But I've swum under the water and I've seen _____!","answer":"coral"},{"type":"meaning_mcq","prompt":"coral","answer":"مرجان","distractors":["كهف","خفّاش","يبحر"]},{"type":"gap_fill","prompt":"Have you ever used goggles and _____?","answer":"flippers"},{"type":"meaning_mcq","prompt":"flippers","answer":"زعانف السباحة","distractors":["قنفذ","نجمة","نظارة سباحة"]},{"type":"gap_fill","prompt":"Have you ever used _____ and flippers?","answer":"goggles"},{"type":"meaning_mcq","prompt":"goggles","answer":"نظارة سباحة","distractors":["كهف","قنفذ","مرجان"]},{"type":"gap_fill","prompt":"I saw wild cats and a _____ while camping.","answer":"hedgehog"},{"type":"meaning_mcq","prompt":"hedgehog","answer":"قنفذ","distractors":["مرجان","قطّ بري","كهف"]},{"type":"gap_fill","prompt":"No, I've _____ used goggles and flippers.","answer":"never"},{"type":"meaning_mcq","prompt":"never","answer":"أبدًا / لم ... قطّ","distractors":["خفّاش","زعانف السباحة","قنفذ"]},{"type":"meaning_mcq","prompt":"sail","answer":"يبحر","distractors":["أبدًا / لم ... قطّ","نجمة","غروب الشمس"]},{"type":"meaning_mcq","prompt":"star","answer":"نجمة","distractors":["يبحر","قنفذ","قطّ بري"]},{"type":"gap_fill","prompt":"Have you ever got up at _____?","answer":"sunrise"},{"type":"meaning_mcq","prompt":"sunrise","answer":"شروق الشمس","distractors":["زعانف السباحة","مرجان","نجمة"]},{"type":"meaning_mcq","prompt":"sunset","answer":"غروب الشمس","distractors":["كهف","زعانف السباحة","مرجان"]},{"type":"meaning_mcq","prompt":"wild cat","answer":"قطّ بري","distractors":["أبدًا / لم ... قطّ","زعانف السباحة","قنفذ"]},{"type":"grammar_reorder","prompt":"goggles / and / used / flippers / I've / never","answer":"I've never used goggles and flippers."},{"type":"grammar_reorder","prompt":"I've / I've / swum / the / water / coral / under / and / seen","answer":"I've swum under the water and I've seen coral!"},{"type":"dialogue_order","lines":["Have you ever sailed in a boat?","Yes, I have. I sailed in a boat at summer camp last year.","Have you ever used goggles and flippers?","No, I've never used goggles and flippers. But I've swum under the water and I've seen coral!"]}],"verified":true,"notes":"Vocabulary from the book contents page; readings and speech bubbles verbatim from Period 1; Arabic meanings authored."},{"number":12,"semester":2,"title":"At the clinic","page":20,"pages":[20,27],"revision":false,"vocabulary":[{"word":"backache","arabic":"ألم الظهر","example":"","source":"book contents / word box","example_note":""},{"word":"bug","arabic":"عدوى / فيروس","example":"There was a stomach bug going around.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"cold","arabic":"زكام","example":"The children had colds.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"cough","arabic":"سعال / يسعل","example":"Ben was sneezing and Amy was coughing all day yesterday.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"earache","arabic":"ألم الأذن","example":"I have an earache and a toothache too.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"fever","arabic":"حمّى","example":"Omar hasn't slept well and he has a fever.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"flu","arabic":"إنفلونزا","example":"Omar had flu and Rania had a sore throat.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"sick","arabic":"مريض","example":"How long have the children been sick?","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"since","arabic":"منذ","example":"They have been sick since last night.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"sneeze","arabic":"يعطس","example":"Ben was sneezing and Amy was coughing all day yesterday.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"sore throat","arabic":"التهاب الحلق","example":"Omar had flu and Rania had a sore throat.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"stomachache","arabic":"ألم المعدة","example":"Many children visited the clinic that morning with a stomachache.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"thirsty","arabic":"عطشان","example":"I'm so hot and thirsty.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"until","arabic":"حتى","example":"They should go home and stay in bed until they feel better.","source":"book contents / word box","example_note":"sentence from the unit text"}],"sentences":["There's a bug going around!"],"dialogues":[{"title":"Period 1 conversation","page":20,"source":"speech bubbles from Pupil's Book; speakers taken from the picture captions","lines":[{"speaker":"Doctor","gender":"m","gender_verified":true,"text":"Good morning! How long have the children been sick?"},{"speaker":"Mum","gender":"f","gender_verified":true,"text":"Since yesterday. I think they both have colds. Ben was sneezing and Amy was coughing all day yesterday."},{"speaker":"Doctor","gender":"m","gender_verified":true,"text":"Good morning! How long have they been sick?"},{"speaker":"Mum","gender":"f","gender_verified":true,"text":"They have been sick since last night. Omar hasn't slept well and he has a fever. Rania has a sore throat."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"I'm so hot and thirsty."},{"speaker":"Doctor","gender":"m","gender_verified":true,"text":"Good afternoon! Oh dear! You don't look very well. How long have you been sick?"},{"speaker":"Hassan","gender":"m","gender_verified":true,"text":"I have an earache and a toothache too."},{"speaker":"Mr Ali","gender":"m","gender_verified":true,"text":"Good morning class!"},{"speaker":"Class","gender":"m","gender_verified":true,"text":"Good morning Mr Ali."},{"speaker":"Mr Ali","gender":"m","gender_verified":true,"text":"You can see that not many pupils are at school today. There's a flu bug going around."}]}],"texts":[{"title":"At the clinic","page":20,"paragraphs":["Ben's mum took the children to the doctor's. The children had colds. They should go home and stay in bed until they feel better.","Omar's mum, Rania and Omar were also at the doctor's. Omar had flu and Rania had a sore throat. The doctor gave them some medicine.","Many children visited the clinic that morning with a stomachache. There was a stomach bug going around.","Mr Ali only had five children in his class the next morning. All the other children were at home. They were not feeling well."]}],"grammar":[{"title":"المضارع التام مع since و for","explanation":"نستعمل since مع نقطة بداية الزمن (since yesterday)، و for مع مدة الزمن (for a week).","examples":["They have been sick since last night.","I've been tired for a week.","How long have you been sick?"]},{"title":"أداة الربط until","explanation":"نستعمل until بمعنى «حتى» لنقول متى ينتهي الشيء.","examples":["They should go home and stay in bed until they feel better."]}],"grammar_en":["المضارع التام مع since و for","أداة الربط until"],"pronunciation":[],"functions":[],"writing":[],"task":"","seeds":[{"type":"meaning_mcq","prompt":"backache","answer":"ألم الظهر","distractors":["إنفلونزا","منذ","ألم المعدة"]},{"type":"gap_fill","prompt":"There was a stomach _____ going around.","answer":"bug"},{"type":"meaning_mcq","prompt":"bug","answer":"عدوى / فيروس","distractors":["حمّى","مريض","عطشان"]},{"type":"meaning_mcq","prompt":"cold","answer":"زكام","distractors":["حمّى","إنفلونزا","يعطس"]},{"type":"meaning_mcq","prompt":"cough","answer":"سعال / يسعل","distractors":["عطشان","التهاب الحلق","إنفلونزا"]},{"type":"gap_fill","prompt":"I have an _____ and a toothache too.","answer":"earache"},{"type":"meaning_mcq","prompt":"earache","answer":"ألم الأذن","distractors":["التهاب الحلق","ألم الظهر","مريض"]},{"type":"gap_fill","prompt":"Omar hasn't slept well and he has a _____.","answer":"fever"},{"type":"meaning_mcq","prompt":"fever","answer":"حمّى","distractors":["ألم المعدة","التهاب الحلق","زكام"]},{"type":"gap_fill","prompt":"Omar had _____ and Rania had a sore throat.","answer":"flu"},{"type":"meaning_mcq","prompt":"flu","answer":"إنفلونزا","distractors":["ألم الأذن","حتى","التهاب الحلق"]},{"type":"gap_fill","prompt":"How long have the children been _____?","answer":"sick"},{"type":"meaning_mcq","prompt":"sick","answer":"مريض","distractors":["ألم المعدة","منذ","سعال / يسعل"]},{"type":"gap_fill","prompt":"They have been sick _____ last night.","answer":"since"},{"type":"meaning_mcq","prompt":"since","answer":"منذ","distractors":["عدوى / فيروس","مريض","التهاب الحلق"]},{"type":"meaning_mcq","prompt":"sneeze","answer":"يعطس","distractors":["زكام","حمّى","التهاب الحلق"]},{"type":"gap_fill","prompt":"Omar had flu and Rania had a _____.","answer":"sore throat"},{"type":"meaning_mcq","prompt":"sore throat","answer":"التهاب الحلق","distractors":["إنفلونزا","ألم المعدة","مريض"]},{"type":"gap_fill","prompt":"Many children visited the clinic that morning with a _____.","answer":"stomachache"},{"type":"meaning_mcq","prompt":"stomachache","answer":"ألم المعدة","distractors":["حتى","حمّى","عدوى / فيروس"]},{"type":"gap_fill","prompt":"I'm so hot and _____.","answer":"thirsty"},{"type":"meaning_mcq","prompt":"thirsty","answer":"عطشان","distractors":["مريض","إنفلونزا","حتى"]},{"type":"gap_fill","prompt":"They should go home and stay in bed _____ they feel better.","answer":"until"},{"type":"meaning_mcq","prompt":"until","answer":"حتى","distractors":["ألم الظهر","عدوى / فيروس","يعطس"]},{"type":"grammar_reorder","prompt":"They / sick / last / night / been / since / have","answer":"They have been sick since last night."},{"type":"grammar_reorder","prompt":"tired / been / a / for / I've / week","answer":"I've been tired for a week."},{"type":"grammar_reorder","prompt":"they / better / should / They / stay / in / bed / feel / go / home / and / until","answer":"They should go home and stay in bed until they feel better."},{"type":"dialogue_order","lines":["Good morning! How long have the children been sick?","Since yesterday. I think they both have colds. Ben was sneezing and Amy was coughing all day yesterday.","Good morning! How long have they been sick?","They have been sick since last night. Omar hasn't slept well and he has a fever. Rania has a sore throat."]}],"verified":true,"notes":"Vocabulary from the book contents page; readings and speech bubbles verbatim from Period 1; Arabic meanings authored."},{"number":13,"semester":2,"title":"Where does rain come from?","page":28,"pages":[28,35],"revision":false,"vocabulary":[{"word":"above","arabic":"فوق","example":"Mr Ali holds a spoon above the hot vapour.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"air","arabic":"هواء","example":"He boils water, it changes into vapour and rises into the air.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"become","arabic":"يصبح","example":"Water changes into vapour and the air becomes wet!","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"change","arabic":"يتغيّر","example":"Mr Ali shows the class how water changes into vapour.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"cloud","arabic":"غيمة","example":"The class understand how the water in the sea and rivers makes clouds.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"correct","arabic":"صحيح","example":"The children think rain comes from many places and they are correct.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"cycle","arabic":"دورة","example":"He shows a picture of the water cycle.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"into","arabic":"إلى (داخل)","example":"Mr Ali shows the class how water changes into vapour.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"rain","arabic":"مطر","example":"Mr Ali asks the class about rain.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"rise","arabic":"يرتفع","example":"He boils water, it changes into vapour and rises into the air.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"sun","arabic":"شمس","example":"The sun is very hot.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"vapour","arabic":"بخار","example":"Mr Ali shows the class how water changes into vapour.","source":"book contents / word box","example_note":"sentence from the unit text"}],"sentences":["That's excellent!","Fantastic!"],"dialogues":[{"title":"Period 1 conversation","page":28,"source":"speech bubbles from Pupil's Book; speakers taken from the picture captions","lines":[{"speaker":"Mr Ali","gender":"m","gender_verified":true,"text":"Where do you think rain comes from?"},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"From the sky."},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"From the clouds."},{"speaker":"Ben","gender":"m","gender_verified":true,"text":"From the sea or rivers."},{"speaker":"Mr Ali","gender":"m","gender_verified":true,"text":"Does anyone want to add anything?"},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"Water changes into vapour and the air becomes wet!"},{"speaker":"Mr Ali","gender":"m","gender_verified":true,"text":"Well done Rania! That's excellent."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"And the vapour is going up into the air. I know hot air rises."},{"speaker":"Mr Ali","gender":"m","gender_verified":true,"text":"Now what do you think is happening?"},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"The vapour is hot but it cools when it rises."},{"speaker":"Ben","gender":"m","gender_verified":true,"text":"The spoon is colder than the air. The vapour changes again and becomes water. Then it falls down."},{"speaker":"Mr Ali","gender":"m","gender_verified":true,"text":"Fantastic! What clever children you are!"},{"speaker":"Mr Ali","gender":"m","gender_verified":true,"text":"OK class, how do you think it rains?"},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"The sun is very hot. The water in the sea becomes warm and some of it changes into vapour."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"The vapour cools and makes clouds."},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"And the clouds get full of water and then it rains!"}]}],"texts":[{"title":"Where does rain come from?","page":28,"paragraphs":["Mr Ali asks the class about rain. He shows a picture of the water cycle. The children think rain comes from many places and they are correct.","Mr Ali shows the class how water changes into vapour. He boils water, it changes into vapour and rises into the air.","Mr Ali holds a spoon above the hot vapour. The vapour touches the spoon and changes into water. It falls.","The class understand how the water in the sea and rivers makes clouds. When the clouds have lots of water, it rains. And then the cycle starts again!"]}],"grammar":[{"title":"المضارع البسيط للحقائق","explanation":"نستعمل المضارع البسيط للحقائق العلمية، ونضيف s للفعل مع he / she / it.","examples":["Hot air rises.","Water changes into vapour.","The vapour cools and makes clouds."]}],"grammar_en":["المضارع البسيط للحقائق"],"pronunciation":[],"functions":[],"writing":[],"task":"","seeds":[{"type":"gap_fill","prompt":"Mr Ali holds a spoon _____ the hot vapour.","answer":"above"},{"type":"meaning_mcq","prompt":"above","answer":"فوق","distractors":["دورة","هواء","بخار"]},{"type":"gap_fill","prompt":"He boils water, it changes into vapour and rises into the _____.","answer":"air"},{"type":"meaning_mcq","prompt":"air","answer":"هواء","distractors":["إلى (داخل)","صحيح","يتغيّر"]},{"type":"meaning_mcq","prompt":"become","answer":"يصبح","distractors":["مطر","دورة","فوق"]},{"type":"meaning_mcq","prompt":"change","answer":"يتغيّر","distractors":["فوق","يرتفع","غيمة"]},{"type":"meaning_mcq","prompt":"cloud","answer":"غيمة","distractors":["فوق","بخار","شمس"]},{"type":"gap_fill","prompt":"The children think rain comes from many places and they are _____.","answer":"correct"},{"type":"meaning_mcq","prompt":"correct","answer":"صحيح","distractors":["مطر","هواء","يرتفع"]},{"type":"gap_fill","prompt":"He shows a picture of the water _____.","answer":"cycle"},{"type":"meaning_mcq","prompt":"cycle","answer":"دورة","distractors":["إلى (داخل)","مطر","صحيح"]},{"type":"gap_fill","prompt":"Mr Ali shows the class how water changes _____ vapour.","answer":"into"},{"type":"meaning_mcq","prompt":"into","answer":"إلى (داخل)","distractors":["مطر","يتغيّر","شمس"]},{"type":"gap_fill","prompt":"Mr Ali asks the class about _____.","answer":"rain"},{"type":"meaning_mcq","prompt":"rain","answer":"مطر","distractors":["صحيح","يصبح","هواء"]},{"type":"meaning_mcq","prompt":"rise","answer":"يرتفع","distractors":["يتغيّر","فوق","بخار"]},{"type":"gap_fill","prompt":"The _____ is very hot.","answer":"sun"},{"type":"meaning_mcq","prompt":"sun","answer":"شمس","distractors":["غيمة","دورة","يتغيّر"]},{"type":"gap_fill","prompt":"Mr Ali shows the class how water changes into _____.","answer":"vapour"},{"type":"meaning_mcq","prompt":"vapour","answer":"بخار","distractors":["صحيح","إلى (داخل)","شمس"]},{"type":"grammar_reorder","prompt":"Hot / air / rises","answer":"Hot air rises."},{"type":"grammar_reorder","prompt":"changes / into / Water / vapour","answer":"Water changes into vapour."},{"type":"dialogue_order","lines":["Where do you think rain comes from?","From the sky.","From the clouds.","From the sea or rivers."]}],"verified":true,"notes":"Vocabulary from the book contents page; readings and speech bubbles verbatim from Period 1; Arabic meanings authored."},{"number":14,"semester":2,"title":"Snow and the water cycle","page":36,"pages":[36,39],"revision":true,"vocabulary":[{"word":"snowman","arabic":"رجل الثلج","example":"Tom and Jemima wanted to play in the snow and make a snowman.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"snow","arabic":"ثلج","example":"Tom and Jemima wanted to play in the snow and make a snowman.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"mountains","arabic":"جبال","example":"One day they visited their uncle in the mountains.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"carrot","arabic":"جزرة","example":"Then he put a carrot nose under the olives.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"scarf","arabic":"وشاح","example":"Then only the hat, scarf, carrot, two olives and two skates were on the grass.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"road","arabic":"طريق","example":"He put salt on the road.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"fever","arabic":"حمّى","example":"But now Tom has a fever.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"sore throat","arabic":"التهاب الحلق","example":"He had a sore throat and was not feeling well.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"became","arabic":"أصبح","example":"The snow became water.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"smaller","arabic":"أصغر","example":"The snowman became smaller and smaller.","source":"book contents / word box","example_note":"sentence from the unit text"}],"sentences":["Oh no!"],"dialogues":[{"title":"Period 1 conversation","page":36,"source":"speech bubbles from Pupil's Book; speakers taken from the picture captions","lines":[{"speaker":"Amy","gender":"f","gender_verified":true,"text":"Ben, have you ever written a story on the computer?"},{"speaker":"Ben","gender":"m","gender_verified":true,"text":"Yes, I have. It's 'Snow and the water cycle'."},{"speaker":"Ben","gender":"m","gender_verified":true,"text":"Have you ever made a snowman?"},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"No, I've never made a snowman."},{"speaker":"Uncle","gender":"m","gender_verified":true,"text":"Oh no. How long have you felt sick?"},{"speaker":"Jemima","gender":"f","gender_verified":true,"text":"Since this morning, but Tom wanted to make a snowman."},{"speaker":"Tom","gender":"m","gender_verified":true,"text":"Have you ever seen a snowman with skates?"},{"speaker":"Jemima","gender":"f","gender_verified":true,"text":"No, I haven't. Ha ha ha! He looks very funny!"},{"speaker":"Tom","gender":"m","gender_verified":true,"text":"What a funny picture, Jemima."},{"speaker":"Jemima","gender":"f","gender_verified":true,"text":"Where has the snowman gone?"},{"speaker":"Tom","gender":"m","gender_verified":true,"text":"Oh dear! The snow has changed into water again."}]}],"texts":[{"title":"Snow and the water cycle","page":36,"paragraphs":["Once upon a time there were two children. Their names were Tom and Jemima. One day they visited their uncle in the mountains.","Tom and Jemima wanted to play in the snow and make a snowman. But now Tom has a fever.","The uncle wanted to drive his car to town, but there was lots of snow on the road. He put salt on the road. The snow became water.","Tom put two olives on the small snowball for eyes. Then he put a carrot nose under the olives.","The sun came out. It was hot. The snowman became smaller and smaller. Then only the hat, scarf, carrot, two olives and two skates were on the grass.","Tom had flu. He had a sore throat and was not feeling well. Jemima wanted to make him feel better. She drew a funny picture."]}],"grammar":[{"title":"مراجعة: المضارع التام مع ever و never و since","explanation":"نراجع لغة الوحدات 10–13.","examples":["Have you ever made a snowman?","No, I've never made a snowman.","How long have you felt sick?"]}],"grammar_en":["مراجعة: المضارع التام مع ever و never و since"],"pronunciation":[],"functions":[],"writing":[],"task":"","seeds":[{"type":"gap_fill","prompt":"Tom and Jemima wanted to play in the snow and make a _____.","answer":"snowman"},{"type":"meaning_mcq","prompt":"snowman","answer":"رجل الثلج","distractors":["وشاح","التهاب الحلق","طريق"]},{"type":"gap_fill","prompt":"Tom and Jemima wanted to play in the _____ and make a snowman.","answer":"snow"},{"type":"meaning_mcq","prompt":"snow","answer":"ثلج","distractors":["رجل الثلج","التهاب الحلق","حمّى"]},{"type":"gap_fill","prompt":"One day they visited their uncle in the _____.","answer":"mountains"},{"type":"meaning_mcq","prompt":"mountains","answer":"جبال","distractors":["رجل الثلج","ثلج","حمّى"]},{"type":"gap_fill","prompt":"Then he put a _____ nose under the olives.","answer":"carrot"},{"type":"meaning_mcq","prompt":"carrot","answer":"جزرة","distractors":["ثلج","أصغر","حمّى"]},{"type":"gap_fill","prompt":"Then only the hat, _____, carrot, two olives and two skates were on the grass.","answer":"scarf"},{"type":"meaning_mcq","prompt":"scarf","answer":"وشاح","distractors":["جزرة","ثلج","طريق"]},{"type":"gap_fill","prompt":"He put salt on the _____.","answer":"road"},{"type":"meaning_mcq","prompt":"road","answer":"طريق","distractors":["أصبح","حمّى","أصغر"]},{"type":"gap_fill","prompt":"But now Tom has a _____.","answer":"fever"},{"type":"meaning_mcq","prompt":"fever","answer":"حمّى","distractors":["جبال","أصبح","ثلج"]},{"type":"gap_fill","prompt":"He had a _____ and was not feeling well.","answer":"sore throat"},{"type":"meaning_mcq","prompt":"sore throat","answer":"التهاب الحلق","distractors":["رجل الثلج","جزرة","جبال"]},{"type":"gap_fill","prompt":"The snow _____ water.","answer":"became"},{"type":"meaning_mcq","prompt":"became","answer":"أصبح","distractors":["جزرة","وشاح","ثلج"]},{"type":"gap_fill","prompt":"The snowman became _____ and smaller.","answer":"smaller"},{"type":"meaning_mcq","prompt":"smaller","answer":"أصغر","distractors":["رجل الثلج","أصبح","جبال"]},{"type":"grammar_reorder","prompt":"Have / made / you / ever / snowman / a","answer":"Have you ever made a snowman?"},{"type":"grammar_reorder","prompt":"a / snowman / made / No, / I've / never","answer":"No, I've never made a snowman."},{"type":"dialogue_order","lines":["Ben, have you ever written a story on the computer?","Yes, I have. It's 'Snow and the water cycle'.","Have you ever made a snowman?","No, I've never made a snowman."]}],"verified":false,"notes":"Revision unit; Vocabulary from the book contents page; readings and speech bubbles verbatim from Period 1; Arabic meanings authored."},{"number":15,"semester":2,"title":"Great explorers","page":40,"pages":[40,47],"revision":false,"vocabulary":[{"word":"agree","arabic":"يوافق","example":"I agree with you.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"compass","arabic":"بوصلة","example":"And this is a compass.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"direction","arabic":"اتجاه","example":"It shows the directions north, south, east and west.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"Earth","arabic":"الأرض","example":"Rania and Omar know about exploring the Earth and the oceans.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"east","arabic":"الشرق","example":"It shows the directions north, south, east and west.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"explore","arabic":"يستكشف","example":"Mr Ali and his class talk about famous explorers.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"explorer","arabic":"مستكشف","example":"Mr Ali and his class talk about famous explorers.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"ocean","arabic":"محيط","example":"Rania and Omar know about exploring the Earth and the oceans.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"south","arabic":"الجنوب","example":"It shows the directions north, south, east and west.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"west","arabic":"الغرب","example":"It shows the directions north, south, east and west.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"woman","arabic":"امرأة","example":"She was the first woman to go into space.","source":"book contents / word box","example_note":"sentence from the unit text"}],"sentences":["I think that's exciting!","I think it's beautiful!","I don't agree with you!"],"dialogues":[{"title":"Period 1 conversation","page":40,"source":"speech bubbles from Pupil's Book; speakers taken from the picture captions","lines":[{"speaker":"Mr Ali","gender":"m","gender_verified":true,"text":"This is a map of the Earth. And this is a compass. It shows the directions north, south, east and west."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"This is Ibn Battuta. He was from the north of Africa. He travelled east to visit the holy cities of Makkah and Madinah."},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"He visited Asia in the east, Europe in the north and Africa in the south, but not North America."},{"speaker":"Mr Ali","gender":"m","gender_verified":true,"text":"This is Jacques Cousteau. He was famous. He was from Europe. The name of his boat was 'Calypso'."},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"I think it is interesting to see a lot of sea plants and sea animals."},{"speaker":"Alia","gender":"f","gender_verified":true,"text":"I agree with you. There's lots of coral under the sea and ocean. I think it's beautiful!"},{"speaker":"Mr Ali","gender":"m","gender_verified":true,"text":"This is Valentina Tereshkova. She was from Asia. She was the first woman to go into space."},{"speaker":"Alia","gender":"f","gender_verified":true,"text":"I don't think travelling in space is safe."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"I don't agree with you, Alia! I think that it is more exciting than exploring the oceans."}]}],"texts":[{"title":"Great explorers","page":40,"paragraphs":["Mr Ali and his class talk about famous explorers. Rania and Omar know about exploring the Earth and the oceans.","Omar and Rania talk about Ibn Battuta. Omar thinks he did the most exciting things. Rania thinks he was very wise because he visited so many interesting places.","Jacques Cousteau sailed in a boat to explore the oceans. He lived on the boat for many months.","Valentina flew and walked in outer space. Her spaceship went around the Earth 48 times!"]}],"grammar":[{"title":"إبداء الرأي والموافقة","explanation":"نعبّر عن رأينا بـ I think ...، ونوافق بـ I agree with you، ونعارض بـ I don't agree with you.","examples":["I think it's beautiful!","I agree with you.","I don't agree with you, Alia!"]},{"title":"مراجعة المقارنة والتفضيل","explanation":"more exciting than للمقارنة، و the most exciting للتفضيل.","examples":["I think that it is more exciting than exploring the oceans.","Omar thinks he did the most exciting things."]}],"grammar_en":["إبداء الرأي والموافقة","مراجعة المقارنة والتفضيل"],"pronunciation":[],"functions":[],"writing":[],"task":"","seeds":[{"type":"gap_fill","prompt":"I _____ with you.","answer":"agree"},{"type":"meaning_mcq","prompt":"agree","answer":"يوافق","distractors":["الأرض","الشرق","يستكشف"]},{"type":"gap_fill","prompt":"And this is a _____.","answer":"compass"},{"type":"meaning_mcq","prompt":"compass","answer":"بوصلة","distractors":["محيط","يستكشف","امرأة"]},{"type":"meaning_mcq","prompt":"direction","answer":"اتجاه","distractors":["يوافق","الجنوب","الشرق"]},{"type":"gap_fill","prompt":"Rania and Omar know about exploring the _____ and the oceans.","answer":"Earth"},{"type":"meaning_mcq","prompt":"Earth","answer":"الأرض","distractors":["الشرق","يستكشف","امرأة"]},{"type":"gap_fill","prompt":"It shows the directions north, south, _____ and west.","answer":"east"},{"type":"meaning_mcq","prompt":"east","answer":"الشرق","distractors":["محيط","مستكشف","يوافق"]},{"type":"meaning_mcq","prompt":"explore","answer":"يستكشف","distractors":["مستكشف","امرأة","الغرب"]},{"type":"meaning_mcq","prompt":"explorer","answer":"مستكشف","distractors":["محيط","امرأة","يستكشف"]},{"type":"meaning_mcq","prompt":"ocean","answer":"محيط","distractors":["الغرب","مستكشف","الشرق"]},{"type":"gap_fill","prompt":"It shows the directions north, _____, east and west.","answer":"south"},{"type":"meaning_mcq","prompt":"south","answer":"الجنوب","distractors":["اتجاه","الشرق","الأرض"]},{"type":"gap_fill","prompt":"It shows the directions north, south, east and _____.","answer":"west"},{"type":"meaning_mcq","prompt":"west","answer":"الغرب","distractors":["امرأة","محيط","اتجاه"]},{"type":"gap_fill","prompt":"She was the first _____ to go into space.","answer":"woman"},{"type":"meaning_mcq","prompt":"woman","answer":"امرأة","distractors":["الجنوب","يوافق","اتجاه"]},{"type":"grammar_reorder","prompt":"I / beautiful / think / it's","answer":"I think it's beautiful!"},{"type":"grammar_reorder","prompt":"I / you / agree / with","answer":"I agree with you."},{"type":"grammar_reorder","prompt":"exploring / I / than / exciting / the / that / more / think / it / oceans / is","answer":"I think that it is more exciting than exploring the oceans."},{"type":"grammar_reorder","prompt":"he / things / most / exciting / Omar / the / thinks / did","answer":"Omar thinks he did the most exciting things."},{"type":"dialogue_order","lines":["This is a map of the Earth. And this is a compass. It shows the directions north, south, east and west.","This is Ibn Battuta. He was from the north of Africa. He travelled east to visit the holy cities of Makkah and Madinah.","He visited Asia in the east, Europe in the north and Africa in the south, but not North America.","This is Jacques Cousteau. He was famous. He was from Europe. The name of his boat was 'Calypso'."]}],"verified":true,"notes":"Vocabulary from the book contents page; readings and speech bubbles verbatim from Period 1; Arabic meanings authored."},{"number":16,"semester":2,"title":"My friends and why I love them","page":48,"pages":[48,55],"revision":false,"vocabulary":[{"word":"brave","arabic":"شجاع","example":"","source":"book contents / word box","example_note":""},{"word":"don't mind","arabic":"لا أمانع","example":"I hope you don't mind me telling my class about you.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"friendly","arabic":"ودود","example":"I love my friend Mohammad because he's helpful and friendly.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"generous","arabic":"كريم","example":"Amy is generous, she lends her books to Alena.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"hate","arabic":"يكره","example":"","source":"book contents / word box","example_note":""},{"word":"helpful","arabic":"متعاون","example":"I love my friend Mohammad because he's helpful and friendly.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"honest","arabic":"صادق / أمين","example":"I love my friend Jordan because he's honest.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"hope","arabic":"يأمل","example":"I hope you don't mind me telling my class about you.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"kind","arabic":"لطيف","example":"And Alena is kind and polite.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"polite","arabic":"مهذّب","example":"And Alena is kind and polite.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"promise","arabic":"يَعِد","example":"And I always promise to give her books back.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"shout","arabic":"يصرخ","example":"But when he gets angry he shouts.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"tell lies","arabic":"يكذب","example":"He never tells lies.","source":"book contents / word box","example_note":"sentence from the unit text"}],"sentences":["I agree with you.","I hope you don't mind but …","No, of course not!"],"dialogues":[{"title":"Period 1 conversation","page":48,"source":"speech bubbles from Pupil's Book; speakers taken from the picture captions","lines":[{"speaker":"Mr Ali","gender":"m","gender_verified":true,"text":"Children, today we are going to talk about our friends and why we love them."},{"speaker":"Alena","gender":"f","gender_verified":true,"text":"I love my friend Amy because she is generous. And I always promise to give her books back."},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"Alena is kind and polite to others. She is good at listening and giving good advice."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"I love my friend Mohammad because he's helpful and friendly. He's teaching me to swim."},{"speaker":"Ben","gender":"m","gender_verified":true,"text":"I love my friend Jordan because he's honest. He never tells lies. But when he gets angry he shouts. I hate shouting!"},{"speaker":"Bilal","gender":"m","gender_verified":true,"text":"I love my big sister Reem. She enjoys writing stories about explorers."},{"speaker":"Bilal","gender":"m","gender_verified":true,"text":"I hope you don't mind me telling my class about you."},{"speaker":"Reem","gender":"f","gender_verified":true,"text":"No, of course not! I don't need to walk in space, I can float."},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"We were talking about our friends at school today. I said, 'I love Alena because she is helpful!'"},{"speaker":"Dad","gender":"m","gender_verified":true,"text":"Oh, that was kind of you! I agree with you – Alena loves helping you."}]}],"texts":[{"title":"My friends and why I love them","page":48,"paragraphs":["Amy and her class are talking about why they love their friends. Amy is generous, she lends her books to Alena. And Alena is kind and polite.","Mohammad and his friends are talking about their best friends and why they love them. Bilal thinks his sister Reem is brave because she can't walk, but she hopes to be a spacewoman.","Reem is playing basketball with Bilal. She thinks he is kind.","Amy and her dad are talking about her day at school."]}],"grammar":[{"title":"ذكر الأسباب بـ because","explanation":"نستعمل because لنذكر سبب حبّنا لأصدقائنا.","examples":["I love my friend Amy because she is generous.","I love my friend Jordan because he's honest."]},{"title":"أفعال يتبعها ing أو to","explanation":"بعض الأفعال يأتي بعدها الفعل مع ing مثل enjoy و hate و love، وبعضها يأتي بعدها to مع الفعل مثل hope و promise و want.","examples":["She enjoys writing stories about explorers.","I hate shouting!","She hopes to be a spacewoman.","I always promise to give her books back."]}],"grammar_en":["ذكر الأسباب بـ because","أفعال يتبعها ing أو to"],"pronunciation":[],"functions":[],"writing":[],"task":"","seeds":[{"type":"meaning_mcq","prompt":"brave","answer":"شجاع","distractors":["يَعِد","يكذب","لا أمانع"]},{"type":"gap_fill","prompt":"I hope you _____ me telling my class about you.","answer":"don't mind"},{"type":"meaning_mcq","prompt":"don't mind","answer":"لا أمانع","distractors":["يكره","متعاون","يَعِد"]},{"type":"gap_fill","prompt":"I love my friend Mohammad because he's helpful and _____.","answer":"friendly"},{"type":"meaning_mcq","prompt":"friendly","answer":"ودود","distractors":["يكره","يكذب","لا أمانع"]},{"type":"gap_fill","prompt":"Amy is _____, she lends her books to Alena.","answer":"generous"},{"type":"meaning_mcq","prompt":"generous","answer":"كريم","distractors":["يأمل","شجاع","يَعِد"]},{"type":"meaning_mcq","prompt":"hate","answer":"يكره","distractors":["صادق / أمين","يكذب","كريم"]},{"type":"gap_fill","prompt":"I love my friend Mohammad because he's _____ and friendly.","answer":"helpful"},{"type":"meaning_mcq","prompt":"helpful","answer":"متعاون","distractors":["يَعِد","يأمل","يصرخ"]},{"type":"gap_fill","prompt":"I love my friend Jordan because he's _____.","answer":"honest"},{"type":"meaning_mcq","prompt":"honest","answer":"صادق / أمين","distractors":["يَعِد","شجاع","يصرخ"]},{"type":"gap_fill","prompt":"I _____ you don't mind me telling my class about you.","answer":"hope"},{"type":"meaning_mcq","prompt":"hope","answer":"يأمل","distractors":["ودود","يصرخ","مهذّب"]},{"type":"gap_fill","prompt":"And Alena is _____ and polite.","answer":"kind"},{"type":"meaning_mcq","prompt":"kind","answer":"لطيف","distractors":["يَعِد","كريم","مهذّب"]},{"type":"gap_fill","prompt":"And Alena is kind and _____.","answer":"polite"},{"type":"meaning_mcq","prompt":"polite","answer":"مهذّب","distractors":["كريم","يكره","ودود"]},{"type":"gap_fill","prompt":"And I always _____ to give her books back.","answer":"promise"},{"type":"meaning_mcq","prompt":"promise","answer":"يَعِد","distractors":["يكره","ودود","مهذّب"]},{"type":"meaning_mcq","prompt":"shout","answer":"يصرخ","distractors":["متعاون","يكذب","يكره"]},{"type":"meaning_mcq","prompt":"tell lies","answer":"يكذب","distractors":["مهذّب","كريم","ودود"]},{"type":"grammar_reorder","prompt":"love / my / Amy / she / friend / I / because / is / generous","answer":"I love my friend Amy because she is generous."},{"type":"grammar_reorder","prompt":"because / my / friend / honest / he's / Jordan / I / love","answer":"I love my friend Jordan because he's honest."},{"type":"grammar_reorder","prompt":"about / explorers / stories / enjoys / writing / She","answer":"She enjoys writing stories about explorers."},{"type":"grammar_reorder","prompt":"shouting / I / hate","answer":"I hate shouting!"},{"type":"dialogue_order","lines":["Children, today we are going to talk about our friends and why we love them.","I love my friend Amy because she is generous. And I always promise to give her books back.","Alena is kind and polite to others. She is good at listening and giving good advice.","I love my friend Mohammad because he's helpful and friendly. He's teaching me to swim."]}],"verified":true,"notes":"Vocabulary from the book contents page; readings and speech bubbles verbatim from Period 1; Arabic meanings authored."},{"number":17,"semester":2,"title":"Good manners","page":56,"pages":[56,63],"revision":false,"vocabulary":[{"word":"clearly","arabic":"بوضوح","example":"","source":"book contents / word box","example_note":""},{"word":"complain","arabic":"يشتكي","example":"Our neighbours will complain.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"in a hurry","arabic":"على عجل","example":"Ben and his family are waiting in a queue in a restaurant.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"interrupt","arabic":"يقاطع","example":"Omar is not happy with Jordan because he interrupted them.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"librarian","arabic":"أمين المكتبة","example":"","source":"book contents / word box","example_note":""},{"word":"library","arabic":"مكتبة","example":"This is a library.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"neighbour","arabic":"جار","example":"Our neighbours will complain.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"notice","arabic":"يلاحظ","example":"A small boy and his mother do not notice the queue and push in rudely.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"push in","arabic":"يتجاوز الدور","example":"A small boy and his mother do not notice the queue and push in rudely.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"queue","arabic":"طابور","example":"Ben and his family are waiting in a queue in a restaurant.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"quickly","arabic":"بسرعة","example":"We came in quickly and didn't notice the queue.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"rudely","arabic":"بوقاحة","example":"A small boy and his mother do not notice the queue and push in rudely.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"take turns","arabic":"يتناوب / يأخذ دوره","example":"Mum says we should take turns.","source":"book contents / word box","example_note":"sentence from the unit text"}],"sentences":["Please don't push in!","Excuse me!","I'm sorry.","Please talk quietly."],"dialogues":[{"title":"Period 1 conversation","page":56,"source":"speech bubbles from Pupil's Book; speakers taken from the picture captions","lines":[{"speaker":"Ben","gender":"m","gender_verified":true,"text":"Excuse me! Please don't push in! There's a queue here."},{"speaker":"Mother","gender":"f","gender_verified":true,"text":"Oh dear, we are sorry. We came in quickly and didn't notice the queue. We'll go to the back."},{"speaker":"Librarian","gender":"f","gender_verified":true,"text":"Excuse me, girls. This is a library. Please talk quietly."},{"speaker":"Rania","gender":"f","gender_verified":true,"text":"Oh sorry!"},{"speaker":"Ben","gender":"m","gender_verified":true,"text":"OK, let's play football."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Where shall we play? Mr Ali thinks we play noisily! Our neighbours will complain."},{"speaker":"Jordan","gender":"m","gender_verified":true,"text":"Hey Ben, did you watch TV last night?"},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Hey Jordan! You shouldn't interrupt while others are speaking. Mum says we should take turns."},{"speaker":"Mr Ali","gender":"m","gender_verified":true,"text":"Amy, please write carefully. I can't read your writing."},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"Sorry!"},{"speaker":"Mr Ali","gender":"m","gender_verified":true,"text":"Amy, I can't hear you. Please speak clearly."},{"speaker":"Amy","gender":"f","gender_verified":true,"text":"Oh I'm sorry."}]}],"texts":[{"title":"Good manners","page":56,"paragraphs":["Ben and his family are waiting in a queue in a restaurant. A small boy and his mother do not notice the queue and push in rudely.","Two girls start to speak loudly. The librarian wants the girls to talk quietly because people come to the library to read and work quietly.","Ben and Omar are talking about where to play. Omar is not happy with Jordan because he interrupted them.","Amy is in a hurry. She is not doing her work carefully."]}],"grammar":[{"title":"ظروف الحال (adverbs of manner)","explanation":"نصف كيف نفعل الشيء بإضافة ly إلى الصفة غالبًا: quick → quickly، clear → clearly، rude → rudely.","examples":["Please speak clearly.","We came in quickly.","A small boy and his mother push in rudely.","Please talk quietly."]}],"grammar_en":["ظروف الحال (adverbs of manner)"],"pronunciation":[],"functions":[],"writing":[],"task":"","seeds":[{"type":"meaning_mcq","prompt":"clearly","answer":"بوضوح","distractors":["يتناوب / يأخذ دوره","على عجل","يلاحظ"]},{"type":"gap_fill","prompt":"Our neighbours will _____.","answer":"complain"},{"type":"meaning_mcq","prompt":"complain","answer":"يشتكي","distractors":["بوقاحة","طابور","يلاحظ"]},{"type":"meaning_mcq","prompt":"in a hurry","answer":"على عجل","distractors":["يشتكي","بسرعة","طابور"]},{"type":"meaning_mcq","prompt":"interrupt","answer":"يقاطع","distractors":["يتجاوز الدور","جار","بسرعة"]},{"type":"meaning_mcq","prompt":"librarian","answer":"أمين المكتبة","distractors":["بسرعة","بوقاحة","على عجل"]},{"type":"gap_fill","prompt":"This is a _____.","answer":"library"},{"type":"meaning_mcq","prompt":"library","answer":"مكتبة","distractors":["يشتكي","يتناوب / يأخذ دوره","بوقاحة"]},{"type":"meaning_mcq","prompt":"neighbour","answer":"جار","distractors":["يقاطع","يتناوب / يأخذ دوره","يتجاوز الدور"]},{"type":"gap_fill","prompt":"A small boy and his mother do not _____ the queue and push in rudely.","answer":"notice"},{"type":"meaning_mcq","prompt":"notice","answer":"يلاحظ","distractors":["بوقاحة","يقاطع","طابور"]},{"type":"gap_fill","prompt":"A small boy and his mother do not notice the queue and _____ rudely.","answer":"push in"},{"type":"meaning_mcq","prompt":"push in","answer":"يتجاوز الدور","distractors":["بوضوح","مكتبة","على عجل"]},{"type":"gap_fill","prompt":"Ben and his family are waiting in a _____ in a restaurant.","answer":"queue"},{"type":"meaning_mcq","prompt":"queue","answer":"طابور","distractors":["بوضوح","يتناوب / يأخذ دوره","جار"]},{"type":"gap_fill","prompt":"We came in _____ and didn't notice the queue.","answer":"quickly"},{"type":"meaning_mcq","prompt":"quickly","answer":"بسرعة","distractors":["بوضوح","أمين المكتبة","يلاحظ"]},{"type":"gap_fill","prompt":"A small boy and his mother do not notice the queue and push in _____.","answer":"rudely"},{"type":"meaning_mcq","prompt":"rudely","answer":"بوقاحة","distractors":["يتناوب / يأخذ دوره","طابور","يشتكي"]},{"type":"gap_fill","prompt":"Mum says we should _____.","answer":"take turns"},{"type":"meaning_mcq","prompt":"take turns","answer":"يتناوب / يأخذ دوره","distractors":["يقاطع","يلاحظ","على عجل"]},{"type":"grammar_reorder","prompt":"Please / clearly / speak","answer":"Please speak clearly."},{"type":"grammar_reorder","prompt":"in / We / quickly / came","answer":"We came in quickly."},{"type":"dialogue_order","lines":["Excuse me! Please don't push in! There's a queue here.","Oh dear, we are sorry. We came in quickly and didn't notice the queue. We'll go to the back.","Excuse me, girls. This is a library. Please talk quietly.","Oh sorry!"]}],"verified":true,"notes":"Vocabulary from the book contents page; readings and speech bubbles verbatim from Period 1; Arabic meanings authored."},{"number":18,"semester":2,"title":"The farmer and the donkey","page":64,"pages":[64,67],"revision":true,"vocabulary":[{"word":"farmer","arabic":"مزارع","example":"Once upon a time a farmer was walking to the town with his donkey and son.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"donkey","arabic":"حمار","example":"Once upon a time a farmer was walking to the town with his donkey and son.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"son","arabic":"ابن","example":"Once upon a time a farmer was walking to the town with his donkey and son.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"ride","arabic":"يركب","example":"Why don't you ride the donkey?","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"carry","arabic":"يحمل","example":"Yes, our donkey has carried us for a long time!","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"angrily","arabic":"بغضب","example":"Two old men stopped them angrily.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"slowly","arabic":"ببطء","example":"The farmer rode the donkey and his son walked slowly behind it.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"turn","arabic":"دور","example":"Come on son, jump down, let's take turns.","source":"book contents / word box","example_note":"sentence from the unit text"},{"word":"promise","arabic":"يَعِد","example":"","source":"book contents / word box","example_note":""},{"word":"agree","arabic":"يوافق","example":"But I agree with you.","source":"book contents / word box","example_note":"sentence from the unit text"}],"sentences":["What a good idea!","But you're right!","Oh dear …"],"dialogues":[{"title":"Period 1 conversation","page":64,"source":"speech bubbles from Pupil's Book; speakers taken from the picture captions","lines":[{"speaker":"Woman","gender":"f","gender_verified":true,"text":"Why don't you ride the donkey? It's strong, put the boy on it!"},{"speaker":"Farmer","gender":"m","gender_verified":true,"text":"What a good idea! Son, jump on the donkey."},{"speaker":"Man","gender":"m","gender_verified":true,"text":"Why's your son riding the donkey? He's young, make him walk!"},{"speaker":"Farmer","gender":"m","gender_verified":true,"text":"Please don't shout! But I agree with you. Come on son, jump down, let's take turns."},{"speaker":"Woman","gender":"f","gender_verified":true,"text":"Hey, look at your son. He's very tired. He should ride the donkey!"},{"speaker":"Farmer","gender":"m","gender_verified":true,"text":"Oh dear … She's right, come on son, it's your turn."},{"speaker":"Girl","gender":"f","gender_verified":true,"text":"Mum, why don't they both ride the donkey?"},{"speaker":"Farmer","gender":"m","gender_verified":true,"text":"You're right. Move up son, I'm getting on."},{"speaker":"Woman","gender":"f","gender_verified":true,"text":"Poor donkey! I can see clearly it is very tired."},{"speaker":"Farmer","gender":"m","gender_verified":true,"text":"Yes, our donkey has carried us for a long time! It's OUR turn to carry HIM now, son."},{"speaker":"Farmer","gender":"m","gender_verified":true,"text":"Oh no, the donkey's running away!"},{"speaker":"Farmer","gender":"m","gender_verified":true,"text":"I promise I will never listen to everyone again and I'll do what I think is best!"}]}],"texts":[{"title":"The farmer and the donkey","page":64,"paragraphs":["Once upon a time a farmer was walking to the town with his donkey and son. A woman stopped them.","The farmer walked next to the donkey and the son rode the donkey. Two old men stopped them angrily.","The farmer rode the donkey and his son walked slowly behind it. A woman and her children stopped them.","The son rode the donkey and the farmer walked slowly behind. A young girl and her mother stopped them.","An old woman stopped them near the town and spoke to them angrily.","The farmer listened to everyone and had no donkey. He and his son went home."]}],"grammar":[{"title":"مراجعة: ظروف الحال والموافقة","explanation":"نراجع لغة الوحدات 15–17: ظروف الحال مثل slowly و angrily، و I agree with you.","examples":["Two old men stopped them angrily.","His son walked slowly behind it.","But I agree with you."]}],"grammar_en":["مراجعة: ظروف الحال والموافقة"],"pronunciation":[],"functions":[],"writing":[],"task":"","seeds":[{"type":"gap_fill","prompt":"Once upon a time a _____ was walking to the town with his donkey and son.","answer":"farmer"},{"type":"meaning_mcq","prompt":"farmer","answer":"مزارع","distractors":["دور","يوافق","بغضب"]},{"type":"gap_fill","prompt":"Once upon a time a farmer was walking to the town with his _____ and son.","answer":"donkey"},{"type":"meaning_mcq","prompt":"donkey","answer":"حمار","distractors":["يحمل","ببطء","يَعِد"]},{"type":"gap_fill","prompt":"Once upon a time a farmer was walking to the town with his donkey and _____.","answer":"son"},{"type":"meaning_mcq","prompt":"son","answer":"ابن","distractors":["يحمل","حمار","دور"]},{"type":"gap_fill","prompt":"Why don't you _____ the donkey?","answer":"ride"},{"type":"meaning_mcq","prompt":"ride","answer":"يركب","distractors":["دور","يَعِد","ببطء"]},{"type":"meaning_mcq","prompt":"carry","answer":"يحمل","distractors":["مزارع","يركب","ابن"]},{"type":"gap_fill","prompt":"Two old men stopped them _____.","answer":"angrily"},{"type":"meaning_mcq","prompt":"angrily","answer":"بغضب","distractors":["يحمل","حمار","يوافق"]},{"type":"gap_fill","prompt":"The farmer rode the donkey and his son walked _____ behind it.","answer":"slowly"},{"type":"meaning_mcq","prompt":"slowly","answer":"ببطء","distractors":["يحمل","يركب","بغضب"]},{"type":"meaning_mcq","prompt":"turn","answer":"دور","distractors":["بغضب","يوافق","ببطء"]},{"type":"meaning_mcq","prompt":"promise","answer":"يَعِد","distractors":["يحمل","يوافق","يركب"]},{"type":"gap_fill","prompt":"But I _____ with you.","answer":"agree"},{"type":"meaning_mcq","prompt":"agree","answer":"يوافق","distractors":["ببطء","بغضب","يركب"]},{"type":"grammar_reorder","prompt":"men / old / Two / angrily / them / stopped","answer":"Two old men stopped them angrily."},{"type":"grammar_reorder","prompt":"His / son / walked / slowly / it / behind","answer":"His son walked slowly behind it."},{"type":"dialogue_order","lines":["Why don't you ride the donkey? It's strong, put the boy on it!","What a good idea! Son, jump on the donkey.","Why's your son riding the donkey? He's young, make him walk!","Please don't shout! But I agree with you. Come on son, jump down, let's take turns."]}],"verified":false,"notes":"Revision unit; Vocabulary from the book contents page; readings and speech bubbles verbatim from Period 1; Arabic meanings authored."}]};
